-- FINAL_VERIFIED_2026_05_15_PK_IDENTITY_REVIEW_4000_NO_DUPLICATE
USE master;
GO

IF DB_ID('itbook') IS NOT NULL
BEGIN
    ALTER DATABASE [itbook] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE [itbook];
END
GO
CREATE DATABASE [itbook];
GO
USE [itbook];
GO


CREATE TABLE [dbo].[category](
    [c_no] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [c_name] NVARCHAR(100) NOT NULL
);
GO
CREATE TABLE [dbo].[library](
    [l_no] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [l_name] NVARCHAR(100) NOT NULL,
    [x] INT NOT NULL,
    [y] INT NOT NULL
);
GO
CREATE TABLE [dbo].[books](
    [b_no] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [c_no] INT NOT NULL,
    [l_no] INT NOT NULL,
    [b_name] NVARCHAR(255) NOT NULL,
    [b_info] NVARCHAR(500) NOT NULL,
    [b_writer] NVARCHAR(100) NOT NULL,
    [b_publisher] NVARCHAR(100) NOT NULL,
    [b_price] INT NOT NULL,
    [b_stock] INT NOT NULL,
    [b_date] DATE NOT NULL,
    CONSTRAINT [FK_books_category] FOREIGN KEY ([c_no]) REFERENCES [dbo].[category]([c_no]),
    CONSTRAINT [FK_books_library] FOREIGN KEY ([l_no]) REFERENCES [dbo].[library]([l_no])
);
GO
CREATE TABLE [dbo].[user](
    [u_no] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [u_name] NVARCHAR(10) NOT NULL,
    [u_id] NVARCHAR(50) NOT NULL,
    [u_pw] NVARCHAR(50) NOT NULL,
    [u_birth] DATE NOT NULL,
    [u_price] INT NOT NULL,
    [u_milage] INT NOT NULL
);
GO
CREATE TABLE [dbo].[orders](
    [o_no] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [u_no] INT NOT NULL,
    [o_price] INT NOT NULL,
    [o_date] DATE NOT NULL,
    [o_books] NVARCHAR(100) NOT NULL,
    CONSTRAINT [FK_orders_user] FOREIGN KEY ([u_no]) REFERENCES [dbo].[user]([u_no])
);
GO
CREATE TABLE [dbo].[review](
    [r_no] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [u_no] INT NOT NULL,
    [r_star] INT NOT NULL,
    [b_no] INT NOT NULL,
    [r_date] DATE NOT NULL,
    [r_keyword] INT NOT NULL,
    [r_content] NVARCHAR(300) NOT NULL,
    CONSTRAINT [FK_review_user] FOREIGN KEY ([u_no]) REFERENCES [dbo].[user]([u_no]),
    CONSTRAINT [FK_review_books] FOREIGN KEY ([b_no]) REFERENCES [dbo].[books]([b_no])
);
GO
CREATE TABLE [dbo].[event](
    [e_no] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [e_books] NVARCHAR(100) NOT NULL,
    [e_startday] DATE NOT NULL,
    [e_endday] DATE NOT NULL,
    [e_discount] INT NOT NULL
);
GO

SET IDENTITY_INSERT [dbo].[category] ON;
