INSERT INTO [dbo].[books] (b_no, c_no, l_no, b_name, b_info, b_writer, b_publisher, b_price, b_stock, b_date) VALUES (1,1,1,'프로젝트 헤일메리','앤디 위어의 SF 장편소설 『프로젝트 헤일메리』는 기억을 잃은 채 우주선에서 깨어난 과학자가 인류의 멸망을 막기 위해 미지의 문제와 맞서는 이야기다. 과학적 상상력과 생존 서사가 긴장감 있게 이어지며, 외로움 속에서도 협력과 희망을 찾아가는 과정이 인상적으로 펼쳐진다.','앤디 위어','알에이치코리아',19800,87,'2026-02-19'),
(2,1,2,'안녕이라 그랬어','김애란의 『안녕이라 그랬어』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 안녕이라 그랬어이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','김애란','문학동네',15120,113,'2025-06-20'),
(3,3,3,'무례한 세상에서 나를 지키는 법','『무례한 세상에서 나를 지키는 법』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 발타자르 그라시안은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','발타자르 그라시안','논픽션',17820,150,'2026-03-13'),
(4,1,4,'제17회 젊은작가상 수상작품집(2026)','김채원 외의 『제17회 젊은작가상 수상작품집(2026)』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 제17회 젊은작가상 수상작품집이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','김채원 외','문학동네',6930,10,'2026-03-31'),
(5,1,5,'나의 완벽한 장례식','조현선의 『나의 완벽한 장례식』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 나의 완벽한 장례식이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','조현선','북로망스',17100,87,'2026-01-21'),
(6,1,6,'바다에서 온 소년','개럿 카의 『바다에서 온 소년』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 바다에서 온 소년이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','개럿 카','북파머스',17820,83,'2026-04-01'),
(7,2,7,'다정한 사람이 이긴다(스페셜 양장 리커버판)','『다정한 사람이 이긴다(스페셜 양장 리커버판)』은 이해인의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','이해인','필름(Feelm)',17100,63,'2026-04-15'),
(8,1,8,'괴테는 모든 것을 말했다','스즈키 유이의 『괴테는 모든 것을 말했다』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 괴테는 모든 것을 말했다이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','스즈키 유이','리프',15300,120,'2025-11-18'),
(9,2,9,'인생을 위한 최소한의 생각','『인생을 위한 최소한의 생각』은 신영준 외의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','신영준 외','상상스퀘어',17820,158,'2026-02-25'),
(10,2,10,'2026 큰별쌤 최태성의 별별한국사 한국사능력검정시험 심화(1,2,3급)(상)','『2026 큰별쌤 최태성의 별별한국사 한국사능력검정시험 심화(1,2,3급)(상)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','최태성','이투스북',17100,165,'2025-12-09'),
(11,2,11,'완벽한 원시인','『완벽한 원시인』은 자청의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','자청','필로틱',19800,177,'2026-03-11'),
(12,1,12,'자몽살구클럽','한로로의 『자몽살구클럽』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 자몽살구클럽이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','한로로','어센틱',10800,92,'2025-07-25'),
(13,2,13,'니체의 초월자','『니체의 초월자』은 프리드리히 니체의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','프리드리히 니체','히읏',15210,129,'2025-10-28'),
(14,3,14,'부처님 말씀대로 살아보니','『부처님 말씀대로 살아보니』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','토니 페르난도','윌마',17010,123,'2026-02-20'),
(15,1,15,'싯다르타','헤르만 헤세의 『싯다르타』는 진리를 찾아 떠나는 한 청년의 방황과 깨달음을 그린 고전 소설이다. 스승의 가르침, 사랑, 세속적 성공과 상실을 지나 스스로의 내면에 다가가는 여정이 차분하게 펼쳐진다. 삶의 의미와 자기 발견을 묵직하게 묻는 작품이다.','헤르만 헤세','민음사',7200,123,'2002-01-20'),
(16,2,16,'2026 큰별쌤 최태성의 별별한국사 한국사능력검정시험 심화(1,2,3급)(하)','『2026 큰별쌤 최태성의 별별한국사 한국사능력검정시험 심화(1,2,3급)(하)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','최태성','이투스북',16650,182,'2025-12-09'),
(17,5,17,'2026 선재국어 최우선 봉투 모의고사','『2026 선재국어 최우선 봉투 모의고사』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','이선재','수비니겨',22500,64,'2026-04-17'),
(18,5,18,'2026 상반기 해커스 GSAT 삼성직무적성검사 Final 봉투모의고사 8회분','『2026 상반기 해커스 GSAT 삼성직무적성검사 Final 봉투모의고사 8회분』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','해커스 GSAT 취업교육연구소','해커스잡',20400,140,'2026-03-05'),
(19,13,19,'읽는기도: 속사람','『읽는기도: 속사람』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','무명의 기도자','더하트',7920,131,'2026-03-25'),
(20,3,20,'피터케이의 이기는 투자 불변의 법칙','『피터케이의 이기는 투자 불변의 법칙』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 피터케이은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','피터케이','21세기북스',19800,198,'2026-04-15'),
(21,2,21,'다크 심리학','『다크 심리학』은 다크 사이드 프로젝트의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','다크 사이드 프로젝트','어센딩',19710,53,'2025-07-31'),
(22,13,22,'읽는기도: 회개스캔','『읽는기도: 회개스캔』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','무명의 기도자','더하트',7920,178,'2026-01-20'),
(23,10,23,'향기로운 꽃은 늠름하게 핀다 19','『향기로운 꽃은 늠름하게 핀다 19』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Saka Mikami','대원씨아이',5400,31,'2026-04-30'),
(24,6,24,'2026 이지패스 ADsP 데이터분석 준전문가','『2026 이지패스 ADsP 데이터분석 준전문가』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','박현민 외','위키북스',27000,82,'2026-01-02'),
(25,1,25,'아르테미스(스폐셜 에디션)','앤디 위어의 『아르테미스』는 달 도시를 배경으로 밀수와 음모에 휘말린 주인공 재즈의 모험을 그린 SF 소설이다. 달 기지의 생활 방식과 과학적 설정이 생생하게 묘사되며, 빠른 사건 전개와 재치 있는 대사가 읽는 재미를 더한다.','앤디 위어','알에이치코리아',17820,141,'2021-05-04'),
(26,1,26,'모순','양귀자의 장편소설 『모순』은 평범해 보이는 가족과 사랑의 관계 속에서 삶이 품은 아이러니를 섬세하게 포착한 작품이다. 주인공 안진진이 주변 인물들의 선택을 바라보며 성장하는 과정이 담겨 있으며, 행복과 불행이 맞물린 인생의 복잡한 얼굴을 깊이 생각하게 한다.','양귀자','쓰다',11700,179,'2013-04-01'),
(27,4,27,'처음 읽는 삼국지 4: 충절의 천 리 길','『처음 읽는 삼국지 4: 충절의 천 리 길』은 어린이와 청소년이 흥미로운 이야기 속에서 지식과 상상력을 함께 키울 수 있도록 구성된 책이다. 익숙한 캐릭터와 사건 전개를 따라가다 보면 역사, 신화, 과학 같은 주제를 자연스럽게 이해하게 된다. 재미와 학습을 함께 잡고 싶은 독자에게 잘 맞는다.','이문열','미래엔아이세움',15120,172,'2026-04-22'),
(28,2,28,'2026 큰별쌤 최태성의 별별한국사 기출 500제 한국사능력검정시험 심화(1,2,3급)','『2026 큰별쌤 최태성의 별별한국사 기출 500제 한국사능력검정시험 심화(1,2,3급)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','최태성','이투스북',19800,168,'2025-12-16'),
(29,5,29,'ETS 토익 정기시험 기출문제집 1000 Vol 5 RC','『ETS 토익 정기시험 기출문제집 1000 Vol 5 RC』은 영어 실력을 체계적으로 다지기 위한 학습서로, ETS의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','ETS','YBM',19800,95,'2025-12-15'),
(30,5,30,'2026 해커스 GSAT 삼성직무적성검사 실전모의고사 10회분','『2026 해커스 GSAT 삼성직무적성검사 실전모의고사 10회분』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','해커스 GSAT 취업교육연구소','해커스잡',20600,33,'2026-02-12'),
(31,3,1,'내면 근력','『내면 근력』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 짐 머피은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','짐 머피','윌북',19800,70,'2026-04-26'),
(32,2,2,'끝까지 해내는 마음은 어떻게 탄생하는가','『끝까지 해내는 마음은 어떻게 탄생하는가』은 웬디 그롤닉 외의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','웬디 그롤닉 외','현대지성',17910,182,'2026-04-07'),
(33,2,3,'다크 심리학 2','『다크 심리학 2』은 다크 사이드 프로젝트의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','다크 사이드 프로젝트','어센딩',21780,89,'2026-04-24'),
(34,3,4,'돈의 심리학(50만 부 기념 뉴 에디션)','모건 하우절의 『돈의 심리학』은 부와 투자에서 숫자보다 중요한 인간의 감정, 습관, 판단 방식을 다룬 경제 교양서다. 실제 사례를 통해 돈을 대하는 태도가 장기적인 결과를 어떻게 바꾸는지 설명하며, 투자보다 먼저 자신의 행동을 돌아보게 한다.','모건 하우절','인플루엔셜',22320,67,'2026-01-14'),
(35,4,5,'물리박사 김상욱의 수상한 연구실 10: 시간 그대로 멈춰라!','『물리박사 김상욱의 수상한 연구실 10: 시간 그대로 멈춰라!』은 어린이와 청소년이 흥미로운 이야기 속에서 지식과 상상력을 함께 키울 수 있도록 구성된 책이다. 익숙한 캐릭터와 사건 전개를 따라가다 보면 역사, 신화, 과학 같은 주제를 자연스럽게 이해하게 된다. 재미와 학습을 함께 잡고 싶은 독자에게 잘 맞는다.','김상욱','아울북',15210,60,'2026-04-15'),
(36,3,6,'자산 토큰 없는 미래는 없다','『자산 토큰 없는 미래는 없다』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 오태민 외은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','오태민 외','거인의정원',26100,47,'2026-04-24'),
(37,1,7,'Project Hail Mary','Andy Weir의 『Project Hail Mary』는 기억을 잃고 우주선에서 깨어난 한 과학자가 인류의 위기를 해결하기 위해 우주의 비밀에 접근하는 SF 소설이다. 과학적 추리와 생존 드라마, 예상 밖의 우정이 함께 전개되어 끝까지 몰입감 있게 읽힌다.','Weir, Andy','Ballantine Books',11700,16,'2022-10-04'),
(38,2,8,'불안(리커버:K)','알랭 드 보통의 『불안』은 현대인이 지위와 인정에 집착하며 느끼는 불안의 원인을 철학과 역사, 예술의 관점에서 살펴본 책이다. 성공과 실패를 바라보는 사회의 시선을 비판적으로 풀어내며, 타인의 평가에서 조금 벗어나는 법을 생각하게 한다.','알랭 드 보통','은행나무',16200,21,'2012-01-04'),
(39,3,9,'돈의 방정식','『돈의 방정식』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 모건 하우절은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','모건 하우절','서삼독',25200,72,'2026-01-16'),
(40,5,10,'ETS 토익 정기시험 기출문제집 1000 Vol 5 LC','『ETS 토익 정기시험 기출문제집 1000 Vol 5 LC』은 영어 실력을 체계적으로 다지기 위한 학습서로, ETS의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','ETS','YBM',19800,131,'2025-12-15'),
(41,3,11,'박곰희 연금 부자 수업','『박곰희 연금 부자 수업』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 박곰희은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','박곰희','인플루엔셜',18900,166,'2025-06-25'),
(42,3,12,'할 수 있다! AI 주식 투자','『할 수 있다! AI 주식 투자』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 머신러너은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','머신러너','에프엔미디어',22500,28,'2026-04-10'),
(43,2,13,'이향인','『이향인』은 라미 카민스키의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','라미 카민스키','21세기북스',15210,126,'2026-03-25'),
(44,9,14,'방구석 미술관','조원재의 『방구석 미술관』은 어렵게 느껴지는 명화와 화가들의 삶을 이야기하듯 풀어낸 예술 교양서다. 작품의 배경과 작가의 인간적인 면모를 함께 소개해 미술을 처음 접하는 독자도 흥미롭게 읽을 수 있으며, 그림을 보는 시야를 넓혀 준다.','조원재','블랙피쉬',16800,116,'2018-08-03'),
(45,4,15,'처음 읽는 그리스 로마 신화 14: 돌아온 오디세우스','『처음 읽는 그리스 로마 신화 14: 돌아온 오디세우스』은 어린이와 청소년이 흥미로운 이야기 속에서 지식과 상상력을 함께 키울 수 있도록 구성된 책이다. 익숙한 캐릭터와 사건 전개를 따라가다 보면 역사, 신화, 과학 같은 주제를 자연스럽게 이해하게 된다. 재미와 학습을 함께 잡고 싶은 독자에게 잘 맞는다.','최설희','미래엔아이세움',15120,171,'2026-03-30'),
(46,12,16,'2026 헝그리스포츠 스포츠지도사 보디빌딩 실기·구술(5종 자격증 포함)+100% 무료강의','『2026 헝그리스포츠 스포츠지도사 보디빌딩 실기·구술(5종 자격증 포함)+100% 무료강의』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','최대로','직업상점',26100,157,'2026-03-20'),
(47,1,17,'마션(스폐셜 에디션)','앤디 위어의 『마션』은 화성에 홀로 남겨진 우주비행사 마크 와트니가 과학 지식과 유머, 끈기로 생존을 이어가는 SF 소설이다. 절망적인 상황을 문제 해결의 과정으로 바꾸어 가는 전개가 흥미롭고, 인간의 지성과 낙관성이 강하게 드러난다.','앤디 위어','알에이치코리아',17820,59,'2021-05-04'),
(48,3,18,'제미나이 주식투자','『제미나이 주식투자』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 조성호은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','조성호','길벗',18000,193,'2026-04-10'),
(49,4,19,'흔한남매 방방곡곡 한국사 1','『흔한남매 방방곡곡 한국사 1』은 어린이와 청소년이 흥미로운 이야기 속에서 지식과 상상력을 함께 키울 수 있도록 구성된 책이다. 익숙한 캐릭터와 사건 전개를 따라가다 보면 역사, 신화, 과학 같은 주제를 자연스럽게 이해하게 된다. 재미와 학습을 함께 잡고 싶은 독자에게 잘 맞는다.','흔한남매','미래엔아이세움',15120,188,'2026-03-31'),
(50,3,20,'굿트레이더 압도적 수익의 주식투자법','『굿트레이더 압도적 수익의 주식투자법』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 굿트레이더(이정훈)은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','굿트레이더(이정훈)','베가북스',22500,108,'2026-05-06'),
(51,1,21,'바깥은 여름','김애란의 『바깥은 여름』은 상실과 죄책감, 관계의 균열을 겪는 인물들의 순간을 섬세하게 담은 소설집이다. 담담한 문장 속에 슬픔과 온기가 함께 흐르며, 평범한 일상 뒤에 숨은 마음의 파동을 오래 바라보게 만든다.','김애란','문학동네',14400,136,'2017-06-28'),
(52,3,22,'주식으로 부자됩시다','『주식으로 부자됩시다』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 박세익은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','박세익','이든하우스',18000,112,'2026-04-10'),
(53,2,23,'위버멘쉬','『위버멘쉬』은 프리드리히 니체의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','프리드리히 니체','떠오름(RISE)',16020,72,'2025-03-14'),
(54,2,24,'어른의 품위(10만 부 기념 교보문고 단독 스페셜 리커버)','『어른의 품위(10만 부 기념 교보문고 단독 스페셜 리커버)』은 최서영의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','최서영','북로망스',17550,47,'2025-10-01'),
(55,3,25,'AI, 신의 탄생 인간의 종말','『AI, 신의 탄생 인간의 종말』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','엘리에저 유드코스키 외','상상스퀘어',19800,177,'2026-04-08'),
(56,1,26,'혼모노','성해나의 『혼모노』는 진짜와 가짜, 믿음과 욕망의 경계에서 흔들리는 인물들을 통해 현대인의 불안을 그려낸 소설이다. 익숙한 현실 속 낯선 균열을 따라가며, 자신이 믿고 있는 세계가 얼마나 불안정한지 돌아보게 한다.','성해나','창비',16200,186,'2025-03-28'),
(57,1,27,'내 이름은 빨강 1','오르한 파묵의 『내 이름은 빨강』은 오스만 제국의 세밀화가들을 둘러싼 살인 사건과 예술적 갈등을 그린 장편소설이다. 사랑과 권력, 동서양 미학의 충돌이 복합적으로 얽히며, 미술을 둘러싼 신념과 욕망을 깊이 있게 보여준다.','오르한 파묵','민음사',11700,11,'2019-10-30'),
(58,1,28,'불편한 편의점','김호연의 『불편한 편의점』은 서울 청파동의 작은 편의점을 배경으로, 저마다의 상처를 가진 사람들이 서로를 이해하며 조금씩 변화하는 이야기다. 낯설고 서툰 인물들이 일상의 공간에서 건네는 위로가 따뜻하게 다가오며, 읽고 나면 사람에 대한 시선이 부드러워진다.','김호연','나무옆의자',12600,120,'2021-04-20'),
(59,5,29,'2026 심우철 실전 동형 모의고사 Season 3','『2026 심우철 실전 동형 모의고사 Season 3』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','심우철','에스티유니타스',13500,118,'2026-04-06'),
(60,5,30,'2026 시대에듀 PASSCODE 투자자산운용사 실제유형 모의고사 + 특별부록','『2026 시대에듀 PASSCODE 투자자산운용사 실제유형 모의고사 + 특별부록』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','유창호','시대에듀',49500,66,'2026-04-03'),
(61,11,1,'스스로 공부하는 아이는 이렇게 키웁니다','『스스로 공부하는 아이는 이렇게 키웁니다』은 가정과 생활, 육아와 건강에 필요한 실용적인 조언을 담은 책이다. 일상에서 바로 적용할 수 있는 방법을 중심으로 구성되어 있어 부담 없이 읽을 수 있다. 더 안정적인 생활 습관과 관계를 만들고 싶은 독자에게 도움이 된다.','이은경','서교책방',17010,55,'2026-03-30'),
(62,2,2,'사랑이 있으니 살아집디다','『사랑이 있으니 살아집디다』은 유시민 외의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','유시민 외','은빛',16200,188,'2026-03-25'),
(63,2,3,'아는 것으로부터의 자유','『아는 것으로부터의 자유』은 지두 크리슈나무르티의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','지두 크리슈나무르티','스노우폭스북스',16920,142,'2026-04-06'),
(64,3,4,'딱 1년만 미쳐라','『딱 1년만 미쳐라』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 리치파카(강연주)은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','리치파카(강연주)','모티브',17820,128,'2026-03-08'),
(65,1,5,'세종의 나라 1','김진명의 『세종의 나라 1』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 세종의 나라 1이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','김진명','이타북스',19800,22,'2026-02-24'),
(66,1,6,'세종의 나라 2','김진명의 『세종의 나라 2』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 세종의 나라 2이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','김진명','이타북스',19800,152,'2026-02-24'),
(67,4,7,'Go Go 카카오프렌즈 자연탐사 15: 유라시아 대초원','『Go Go 카카오프렌즈 자연탐사 15: 유라시아 대초원』은 어린이와 청소년이 흥미로운 이야기 속에서 지식과 상상력을 함께 키울 수 있도록 구성된 책이다. 익숙한 캐릭터와 사건 전개를 따라가다 보면 역사, 신화, 과학 같은 주제를 자연스럽게 이해하게 된다. 재미와 학습을 함께 잡고 싶은 독자에게 잘 맞는다.','조주희','아울북',15210,73,'2026-04-15'),
(68,2,8,'죽고 싶지만 떡볶이는 먹고 싶어','백세희의 『죽고 싶지만 떡볶이는 먹고 싶어』는 우울과 불안을 겪는 저자가 상담 과정을 기록하며 마음의 상태를 솔직하게 드러낸 에세이다. 거창한 해답보다 흔들리는 감정을 있는 그대로 바라보게 하며, 완벽하지 않아도 살아갈 수 있다는 작은 위로를 전한다.','백세희','흔',12420,110,'2018-06-20'),
(69,5,9,'김재우의 기본 동사 100','『김재우의 기본 동사 100』은 영어 실력을 체계적으로 다지기 위한 학습서로, 김재우의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','김재우','상상스퀘어',19800,126,'2025-12-10'),
(70,2,10,'사후생','『사후생』은 엘리자베스 퀴블러 로스의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','엘리자베스 퀴블러 로스','(재)여해와함께',11700,44,'2020-03-31'),
(71,1,11,'은하수를 여행하는 히치하이커를 위한 안내서 1','더글러스 애덤스의 『은하수를 여행하는 히치하이커를 위한 안내서』는 지구 멸망 이후 우주로 던져진 평범한 인간의 황당한 모험을 그린 SF 코미디다. 기발한 상상력과 풍자가 가득해 우주, 인간, 문명에 대한 익살스러운 질문을 던진다.','더글러스 애덤스','책세상',12600,128,'2018-05-05'),
(72,3,12,'하버드의 특별한 시간관리 수업','『하버드의 특별한 시간관리 수업』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 쉬셴장은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','쉬셴장','지니의서재',16920,180,'2026-04-20'),
(73,5,13,'2026 써니 행정법총론 봉투모의고사 8회분','『2026 써니 행정법총론 봉투모의고사 8회분』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','박준철','제이씨에듀',10800,145,'2026-04-08'),
(74,1,14,'작별하지 않는다','한강의 『작별하지 않는다』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 작별하지 않는다이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','한강','문학동네',15120,153,'2021-09-09'),
