(76,1,16,'소년이 온다','한강의 『소년이 온다』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 소년이 온다이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','한강','창비',13500,91,'2014-05-19'),
(77,1,17,'아몬드','손원평의 『아몬드』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 아몬드이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','손원평','창비',12000,130,'2017-03-31'),
(78,5,18,'2026 해커스공무원 실전동형모의고사 영어 2 12회분(지방직 9급)','『2026 해커스공무원 실전동형모의고사 영어 2 12회분(지방직 9급)』은 영어 실력을 체계적으로 다지기 위한 학습서로, 해커스 공무원시험연구소의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','해커스 공무원시험연구소','해커스공무원',17100,166,'2026-04-03'),
