(80,4,20,'에그박사 18','『에그박사 18』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 에그박사 18의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','에그박사','미래엔아이세움',15120,139,'2026-04-22'),
(81,3,21,'부의 자율주행: AI MONEY FLOW','『부의 자율주행: AI MONEY FLOW』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','AI 머니(이진재)','모티브',19800,119,'2026-03-31'),
(82,3,22,'명료함','『명료함』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 탁민 오은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','탁민 오','탁희재',17820,150,'2026-02-04'),
(83,1,23,'절창','구병모의 『절창』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 절창이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','구병모','문학동네',16200,124,'2025-09-17'),
(84,1,24,'이중 하나는 거짓말','김애란의 『이중 하나는 거짓말』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 이중 하나는 거짓말이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','김애란','문학동네',14400,50,'2024-08-27'),
(85,1,25,'급류','정대건의 『급류』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 급류이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','정대건','민음사',12600,200,'2022-12-22'),
(86,2,26,'꽃을 보듯 너를 본다(100만 부 기념 에디션)(리커버:K)','『꽃을 보듯 너를 본다(100만 부 기념 에디션)(리커버:K)』은 나태주의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','나태주','지혜',11700,131,'2020-11-30'),
(87,3,27,'AI 시대 강자로 살아남는 법','『AI 시대 강자로 살아남는 법』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','리샹룽','알토북스',16920,125,'2026-04-10'),
(88,3,28,'평생 월 500만 원 받는 월배당 ETF','『평생 월 500만 원 받는 월배당 ETF』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 배당의만장은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','배당의만장','노티스',20700,76,'2026-03-23'),
(89,3,29,'캔들차트 하나로 끝내는 추세추종 투자','『캔들차트 하나로 끝내는 추세추종 투자』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 성승현은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','성승현','포르체',22500,73,'2026-01-07'),
(90,3,30,'진보를 위한 주식투자','『진보를 위한 주식투자』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 이광수은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','이광수','21세기북스',19800,173,'2025-12-17'),
(91,3,1,'생각의 도약','『생각의 도약』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 도야마 시게히코은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','도야마 시게히코','페이지2북스',16200,80,'2025-01-29'),
(92,4,2,'엄마가 유령이 되었어!','『엄마가 유령이 되었어!』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 엄마가 유령이 되었어!의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','노부미','길벗어린이',10800,143,'2016-05-15'),
(93,5,3,'2026~2027 이진욱 세무사의 공무원 지방세법 기출플러스','『2026~2027 이진욱 세무사의 공무원 지방세법 기출플러스』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','이진욱','배움',27000,134,'2026-04-15'),
(94,7,4,'이토록 쓸모 있는 수학적 사고','『이토록 쓸모 있는 수학적 사고』은 과학과 기술의 원리를 이해하기 쉽게 풀어낸 교양서다. 복잡하게 느껴지는 개념을 생활 속 사례와 연결해 설명하며, 세상을 바라보는 과학적 시선을 넓혀 준다. 호기심을 지식으로 발전시키고 싶은 독자에게 어울린다.','류쉐펑','미디어숲',19800,170,'2026-04-10'),
(95,5,5,'2026 문동균 한국사 지방직 대비 실전 봉투모의고사(봉투형)','『2026 문동균 한국사 지방직 대비 실전 봉투모의고사(봉투형)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','문동균','에스티유니타스',11700,71,'2026-04-03'),
(96,1,6,'인터메초','샐리 루니의 『인터메초』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 인터메초이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','샐리 루니','은행나무',18900,80,'2026-02-05'),
(97,6,7,'2026 ADsP 데이터분석 준전문가','『2026 ADsP 데이터분석 준전문가』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','윤종식','데이터에듀',27900,122,'2025-12-26'),
(98,1,8,'죽은 왕녀를 위한 파반느(양장 특별판)','박민규의 『죽은 왕녀를 위한 파반느(양장 특별판)』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 죽은 왕녀를 위한 파반느이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','박민규','위즈덤하우스',18000,29,'2025-11-19'),
(99,2,9,'행복할 거야 이래도 되나 싶을 정도로(10만 부 기념 교보문고 단독 리커버)','『행복할 거야 이래도 되나 싶을 정도로(10만 부 기념 교보문고 단독 리커버)』은 일홍의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','일홍','부크럼',16200,192,'2024-07-29'),
(100,1,10,'데미안','헤르만 헤세의 『데미안』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 데미안이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','헤르만 헤세','민음사',7200,83,'2009-01-20'),
(101,9,11,'캐릭터 심리 사전','『캐릭터 심리 사전』은 예술과 대중문화를 더 깊이 감상할 수 있도록 돕는 문화 교양서다. 작품이 만들어진 배경과 표현 방식, 창작자의 고민을 함께 다루어 보는 재미와 이해의 폭을 넓힌다.','린다 N. 에델스타인','부키',25200,70,'2026-04-22'),
(102,2,12,'최소한의 삼국지(10만 부 기념 도원결의 에디션)','『최소한의 삼국지(10만 부 기념 도원결의 에디션)』은 어린이와 청소년이 흥미로운 이야기 속에서 지식과 상상력을 함께 키울 수 있도록 구성된 책이다. 익숙한 캐릭터와 사건 전개를 따라가다 보면 역사, 신화, 과학 같은 주제를 자연스럽게 이해하게 된다. 재미와 학습을 함께 잡고 싶은 독자에게 잘 맞는다.','최태성','프런트페이지',17550,79,'2025-11-18'),
(103,3,13,'아주 작은 습관의 힘(50만 부 기념 스페셜 에디션)','『아주 작은 습관의 힘(50만 부 기념 스페셜 에디션)』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 제임스 클리어은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','제임스 클리어','비즈니스북스',16200,95,'2019-02-26'),
(104,1,14,'브람스를 좋아하세요','프랑수아즈 사강의 『브람스를 좋아하세요』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 브람스를 좋아하세요이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','프랑수아즈 사강','민음사',9000,91,'2008-05-02'),
(105,1,15,'달러구트 꿈 백화점','이미예의 『달러구트 꿈 백화점』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 달러구트 꿈 백화점이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','이미예','팩토리나인',12420,100,'2020-07-08'),
(106,5,16,'2026 이유진 국어 화제의 모의고사 봉투형','『2026 이유진 국어 화제의 모의고사 봉투형』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','이유진','고시동네',18000,30,'2026-04-13'),
(107,2,17,'삶으로 다시 날아오르기','『삶으로 다시 날아오르기』은 빌헬름 슈미트의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','빌헬름 슈미트','피카(FIKA)',16200,45,'2026-03-16'),
(108,3,18,'인생 마지막에 쓰는 주식투자 교과서','『인생 마지막에 쓰는 주식투자 교과서』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 정규준은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','정규준','애덤스미스',22500,48,'2026-03-01'),
(109,11,19,'0~3세 기적의 뇌과학 육아','『0~3세 기적의 뇌과학 육아』은 가정과 생활, 육아와 건강에 필요한 실용적인 조언을 담은 책이다. 일상에서 바로 적용할 수 있는 방법을 중심으로 구성되어 있어 부담 없이 읽을 수 있다. 더 안정적인 생활 습관과 관계를 만들고 싶은 독자에게 도움이 된다.','그리어 커센바움','21세기북스',18000,69,'2024-07-03'),
(110,2,20,'초역 부처의 말','『초역 부처의 말』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','코이케 류노스케','포레스트북스',16020,108,'2024-05-30'),
(111,7,21,'코스모스','『코스모스』은 과학과 기술의 원리를 이해하기 쉽게 풀어낸 교양서다. 복잡하게 느껴지는 개념을 생활 속 사례와 연결해 설명하며, 세상을 바라보는 과학적 시선을 넓혀 준다. 호기심을 지식으로 발전시키고 싶은 독자에게 어울린다.','칼 세이건','사이언스북스',19800,187,'2010-01-20'),
(112,2,22,'사랑은 결국 타이밍','『사랑은 결국 타이밍』은 박여름의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','박여름','히읏',16380,49,'2026-04-17'),
(113,2,23,'러브 온 더 락','『러브 온 더 락』은 고선경의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','고선경','창비',11700,190,'2026-04-17'),
(114,5,24,'JLPT(일본어능력시험) 한권으로 끝내기 N3','『JLPT(일본어능력시험) 한권으로 끝내기 N3』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','이치우 외','다락원',25200,64,'2026-04-06'),
(115,3,25,'사람을 얻는 힘 인간력','『사람을 얻는 힘 인간력』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 다사카 히로시은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','다사카 히로시','북플레저',18000,26,'2026-03-18'),
(116,2,26,'모든 것은 별에서 시작되었다','『모든 것은 별에서 시작되었다』은 조앤 베이커의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','조앤 베이커','북플레저',19800,116,'2026-02-11'),
(117,5,27,'해커스 토익 기출 VOCA(보카)','『해커스 토익 기출 VOCA(보카)』은 영어 실력을 체계적으로 다지기 위한 학습서로, David Cho의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','David Cho','해커스어학연구소',11610,114,'2026-01-05'),
(118,5,28,'2026 시대에듀 All-New KB국민은행 필기전형 봉투모의고사 9회분','『2026 시대에듀 All-New KB국민은행 필기전형 봉투모의고사 9회분』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','SDC','시대고시기획',18000,94,'2025-12-15'),
(119,3,29,'자본주의 시대에서 살아남기 위한 최소한의 경제 공부','『자본주의 시대에서 살아남기 위한 최소한의 경제 공부』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 백억남(김욱현)은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','백억남(김욱현)','하이스트',25200,148,'2025-12-04'),
(120,3,30,'렛뎀 이론','『렛뎀 이론』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 멜 로빈스은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','멜 로빈스','비즈니스북스',18000,129,'2025-08-30'),
(121,2,1,'너를 아끼며 살아라','『너를 아끼며 살아라』은 나태주의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','나태주','더블북',16650,116,'2025-06-12'),
(122,3,2,'왜 일하는가','『왜 일하는가』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 이나모리 가즈오은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','이나모리 가즈오','다산북스',16200,25,'2021-04-12'),
(123,4,3,'긴긴밤','『긴긴밤』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 긴긴밤의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','루리','문학동네',11250,62,'2021-02-03'),
(124,1,4,'채식주의자','한강의 『채식주의자』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 채식주의자이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','한강','창비',13500,90,'2022-03-28'),
(125,8,5,'썬킴의 거침없는 세계사','『썬킴의 거침없는 세계사』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','썬킴','지식의숲',17820,109,'2021-04-26'),
(126,3,6,'더 기버 1','『더 기버 1』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 밥 버그 외은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','밥 버그 외','오팬하우스',18000,159,'2026-03-30'),
(127,3,7,'박태웅의 AI 강의 2026','『박태웅의 AI 강의 2026』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','박태웅','한빛비즈',20700,188,'2026-03-20'),
(128,1,8,'내 이름은 빨강 2','오르한 파묵의 『내 이름은 빨강 2』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 내 이름은 빨강 2이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','오르한 파묵','민음사',11700,15,'2019-10-30'),
(129,3,9,'생각에 관한 생각','『생각에 관한 생각』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 대니얼 카너먼은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','대니얼 카너먼','김영사',26820,157,'2018-03-30'),
(130,10,10,'황천의 츠가이 10','『황천의 츠가이 10』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Hiromu Arakawa','대원씨아이',5850,107,'2026-04-20'),
(131,5,11,'2026 해커스공무원 매일 하프모의고사 영어 4 24회분(지방직 9급)','『2026 해커스공무원 매일 하프모의고사 영어 4 24회분(지방직 9급)』은 영어 실력을 체계적으로 다지기 위한 학습서로, 해커스 공무원시험연구소의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','해커스 공무원시험연구소','해커스공무원',15210,132,'2026-03-20'),
(132,2,12,'구원에게','『구원에게』은 정영욱의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','정영욱','부크럼',16200,11,'2026-02-05'),
(133,2,13,'큰별쌤 최태성의 별별한국사 시대별 기출문제집 한국사능력검정시험 심화(1,2,3급)','『큰별쌤 최태성의 별별한국사 시대별 기출문제집 한국사능력검정시험 심화(1,2,3급)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','최태성','이투스북',17730,100,'2025-06-11'),
(134,2,14,'어른의 행복은 조용하다','『어른의 행복은 조용하다』은 태수의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','태수','페이지2북스',16020,86,'2024-11-04'),
(135,5,15,'2026 시대에듀 All-New CJ그룹 CAT 온라인 인적성검사 통합기본서','『2026 시대에듀 All-New CJ그룹 CAT 온라인 인적성검사 통합기본서』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','SDC','시대고시기획',16800,109,'2025-12-15'),
(136,10,16,'디그 잇 1','『디그 잇 1』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Yoshidamaru','학산문화사',6300,117,'2026-04-23'),
(137,8,17,'지도로 보아야 보인다 2','『지도로 보아야 보인다 2』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','에밀리 오브리 외','사이',27900,147,'2026-04-10'),
(138,8,18,'최소한의 한국사(5천 년 역사가 단숨에 이해되는)','『최소한의 한국사(5천 년 역사가 단숨에 이해되는)』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','최태성','프런트페이지',17820,198,'2026-04-01'),
(139,4,19,'마법천자문 70: 반드시 이룬다! 목표','『마법천자문 70: 반드시 이룬다! 목표』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 마법천자문 70: 반드시 이룬다! 목표의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','알에스미디어','아울북',14310,149,'2026-03-18'),
(140,3,20,'어떻게 나를 만들 것인가','『어떻게 나를 만들 것인가』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 수지 웰치은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','수지 웰치','토네이도',18000,164,'2026-03-16'),
(141,3,21,'주식투자 무작정 따라하기(2026)','『주식투자 무작정 따라하기(2026)』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 윤재수은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','윤재수','길벗',22500,66,'2026-01-30'),
(142,8,22,'지도로 보아야 보인다','『지도로 보아야 보인다』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','에밀리 오브리 외','사이',26820,134,'2024-07-30'),
(143,2,23,'여덟 단어','『여덟 단어』은 박웅현의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','박웅현','인티앤',15300,66,'2023-06-15'),
(144,8,24,'총 균 쇠','『총 균 쇠』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','재레드 다이아몬드','김영사',26820,79,'2023-05-11'),
(145,4,25,'기발하고 신기한  수학의 재미(상편)','『기발하고 신기한 수학의 재미(상편)』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 기발하고 신기한 수학의 재미의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','천융밍','미디어숲',16020,121,'2022-07-20'),
(146,1,26,'채식주의자','한강의 『채식주의자』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 채식주의자이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','한강','창비',15300,134,'2022-03-28'),
(147,1,27,'달려라,아비(리마스터판)','김애란의 『달려라,아비(리마스터판)』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 달려라,아비이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','김애란','창비',13500,17,'2019-09-25'),
(148,2,28,'명상록','『명상록』은 마르쿠스 아우렐리우스의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','마르쿠스 아우렐리우스','현대지성',10800,109,'2018-04-02'),
(149,5,29,'2026 해커스 GSAT 삼성직무적성검사 통합 기본서 최신기출유형+실전모의고사 (수리/추리)','『2026 해커스 GSAT 삼성직무적성검사 통합 기본서 최신기출유형+실전모의고사 (수리/추리)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','해커스 취업교육연구소','해커스잡',22600,96,'2026-01-09'),
(150,8,30,'기획된 내란','『기획된 내란』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','이희천','대추나무',15300,181,'2026-04-15'),
(151,3,1,'부의 사다리에 올라타라','『부의 사다리에 올라타라』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 닉 매기울리은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','닉 매기울리','알에이치코리아',20700,183,'2026-04-10'),
(152,3,2,'투자 불패의 법칙','『투자 불패의 법칙』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 배리 리트홀츠은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','배리 리트홀츠','인플루엔셜',26820,113,'2026-03-27'),
(153,8,3,'질서의 소멸','『질서의 소멸』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','이춘근','보다나은',18000,195,'2026-03-27'),
(154,9,4,'왕과 사는 남자 각본집','『왕과 사는 남자 각본집』은 예술과 대중문화를 더 깊이 감상할 수 있도록 돕는 문화 교양서다. 작품이 만들어진 배경과 표현 방식, 창작자의 고민을 함께 다루어 보는 재미와 이해의 폭을 넓힌다.','황성구 외','플레인아카이브',16200,52,'2026-03-23'),
(155,7,5,'이기적 유전자','『이기적 유전자』은 과학과 기술의 원리를 이해하기 쉽게 풀어낸 교양서다. 복잡하게 느껴지는 개념을 생활 속 사례와 연결해 설명하며, 세상을 바라보는 과학적 시선을 넓혀 준다. 호기심을 지식으로 발전시키고 싶은 독자에게 어울린다.','리처드 도킨스','을유문화사',18000,129,'2023-01-30'),
(156,3,6,'월가의 영웅','『월가의 영웅』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 피터 린치 외은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','피터 린치 외','국일증권경제연구소',23400,42,'2021-07-30'),
(157,9,7,'난처한 미술 이야기 1','『난처한 미술 이야기 1』은 예술과 문화의 세계를 더 가까이 이해하도록 돕는 책이다. 작품과 창작자의 배경을 함께 살펴보며 단순한 감상을 넘어 표현 방식과 시대적 의미까지 생각하게 한다. 문화 콘텐츠를 깊이 있게 즐기고 싶은 독자에게 어울린다.','양정무','사회평론',19800,169,'2016-05-09'),
(158,10,8,'3월의 라이온 18','『3월의 라이온 18』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Chica Umino','학산문화사',7200,146,'2026-04-09'),
(159,5,9,'가브리엘의 잉글리시 다이어리','『가브리엘의 잉글리시 다이어리』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','Thomas Gabrielle Allanta','상상스퀘어',24300,16,'2025-10-01'),
(160,11,10,'임신 출산 육아 대백과(2025-2026)','『임신 출산 육아 대백과(2025-2026)』은 가정과 생활, 육아와 건강에 필요한 실용적인 조언을 담은 책이다. 일상에서 바로 적용할 수 있는 방법을 중심으로 구성되어 있어 부담 없이 읽을 수 있다. 더 안정적인 생활 습관과 관계를 만들고 싶은 독자에게 도움이 된다.','삼성출판사 편집부','삼성출판사',17550,110,'2025-07-30'),
(161,5,11,'2025 시원스쿨 토익 기출유형 모의고사 3회분','『2025 시원스쿨 토익 기출유형 모의고사 3회분』은 영어 실력을 체계적으로 다지기 위한 학습서로, 시원스쿨어학연구소의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','시원스쿨어학연구소','시원스쿨닷컴',7920,161,'2025-01-22'),
(162,2,12,'내 언어의 한계는 내 세계의 한계이다','『내 언어의 한계는 내 세계의 한계이다』은 김종원의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','김종원','마인드셋(Mindset)',16920,154,'2024-05-29'),
(163,5,13,'해커스 일본어 첫걸음: 기초20일 독학 완성!','『해커스 일본어 첫걸음: 기초20일 독학 완성!』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','해커스 일본어연구소','해커스어학연구소',12510,179,'2024-05-07'),
(164,2,14,'쇼펜하우어 인생수업(30만 부 기념 개정증보판)','『쇼펜하우어 인생수업(30만 부 기념 개정증보판)』은 쇼펜하우어의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','쇼펜하우어','하이스트',15750,16,'2024-02-20'),
(165,3,15,'돈의 속성(400쇄 리커버에디션)','『돈의 속성(400쇄 리커버에디션)』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 김승호은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','김승호','스노우폭스북스',16020,31,'2020-06-15'),
(166,2,16,'사랑의 기술','『사랑의 기술』은 에리히 프롬의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','에리히 프롬','문예출판사',15300,174,'2019-09-01'),
(167,13,17,'구약성경과 신들','『구약성경과 신들』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','주원준','한님성서연구소',13500,119,'2018-04-02'),
(168,3,18,'월급쟁이 루지 부의 설계','『월급쟁이 루지 부의 설계』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 루지은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','루지','한국경제신문',20700,44,'2026-04-29'),
(169,5,19,'2026 고시넷 MG새마을금고 NCS 기출예상모의고사 8회','『2026 고시넷 MG새마을금고 NCS 기출예상모의고사 8회』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','고시넷 NCS 연구소','고시넷',23400,128,'2026-04-10'),
(170,14,20,'매일성경 개역개정(2026년5/6월호)','『매일성경 개역개정(2026년5/6월호)』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','성서유니온 편집부','성서유니온',4750,56,'2026-04-07'),
(171,1,21,'사십구년유월, 어느 날의 일','김석의 『사십구년유월, 어느 날의 일』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 사십구년유월, 어느 날의 일이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','김석','바른북스',19800,22,'2026-04-03'),
(172,4,22,'프린세스 캐치! 티니핑 동화5: 다이아나핑을 구하라!','『프린세스 캐치! 티니핑 동화5: 다이아나핑을 구하라!』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 프린세스 캐치! 티니핑 동화5: 다이아나핑을 구하라!의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','SAMG','아이휴먼',14400,76,'2026-03-25'),
(173,2,23,'우리가 사랑한 도시','『우리가 사랑한 도시』은 김지윤 외의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','김지윤 외','북다',15750,107,'2026-03-12'),
(174,8,24,'무극화 시대','『무극화 시대』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','조한범','보다나은',18000,93,'2026-02-06'),
(175,4,25,'나쁜 일이 있어도 나쁜 날은 아니야','『나쁜 일이 있어도 나쁜 날은 아니야』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 나쁜 일이 있어도 나쁜 날은 아니야의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','정문정','서교책방',15120,64,'2026-01-28'),
(176,3,26,'더블 클릭','『더블 클릭』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 알간지은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','알간지','생각정원',17100,126,'2026-01-05'),
(177,3,27,'대형주 추세추종 투자법칙','『대형주 추세추종 투자법칙』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 이종호(전황)은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','이종호(전황)','사피엔테스',19800,93,'2025-11-05'),
(178,5,28,'ETS 토익 단기공략 750+(LC+RC)','『ETS 토익 단기공략 750+(LC+RC)』은 영어 실력을 체계적으로 다지기 위한 학습서로, ETS의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','ETS','YBM',17550,96,'2025-07-01'),
(179,5,29,'김재우의 기초 영어회화 100','『김재우의 기초 영어회화 100』은 영어 실력을 체계적으로 다지기 위한 학습서로, 김재우의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','김재우','상상스퀘어',17010,107,'2024-12-04'),
(180,5,30,'Go! 독학 일본어 첫걸음','『Go! 독학 일본어 첫걸음』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','최유리 외','시원스쿨닷컴',12510,81,'2024-11-01'),
(181,2,1,'제철 행복','『제철 행복』은 김신지의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','김신지','인플루엔셜',16020,117,'2024-04-25'),
(182,4,2,'아몬드(청소년)','『아몬드(청소년)』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 아몬드의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','손원평','다즐링',15120,74,'2023-07-14'),
(183,1,3,'이방인','알베르 카뮈의 『이방인』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 이방인이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','알베르 카뮈','민음사',9000,30,'2019-09-02'),
(184,5,4,'JLPT(일본어능력시험) 한권으로 끝내기 N2','『JLPT(일본어능력시험) 한권으로 끝내기 N2』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','이치우 외','다락원',25200,130,'2026-03-26'),
(185,4,5,'옛날옛날 늑대가 돌아다니던 시절에','『옛날옛날 늑대가 돌아다니던 시절에』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 옛날옛날 늑대가 돌아다니던 시절에의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','앤서니 브라운','웅진주니어',15120,14,'2026-03-23'),
(186,7,6,'이토록 위대한 몸','『이토록 위대한 몸』은 과학과 기술의 원리를 이해하기 쉽게 풀어낸 교양서다. 복잡하게 느껴지는 개념을 생활 속 사례와 연결해 설명하며, 세상을 바라보는 과학적 시선을 넓혀 준다. 호기심을 지식으로 발전시키고 싶은 독자에게 어울린다.','줄리아 엔더스','21세기북스',21600,148,'2026-03-04'),
(187,1,7,'내 심장을 쏴라','정유정의 『내 심장을 쏴라』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 내 심장을 쏴라이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','정유정','은행나무',16200,23,'2026-02-06'),
(188,7,8,'2026 직8딴 직접 8일 만에 딴 산업안전기사 필기','『2026 직8딴 직접 8일 만에 딴 산업안전기사 필기』은 과학과 기술의 원리를 이해하기 쉽게 풀어낸 교양서다. 복잡하게 느껴지는 개념을 생활 속 사례와 연결해 설명하며, 세상을 바라보는 과학적 시선을 넓혀 준다. 호기심을 지식으로 발전시키고 싶은 독자에게 어울린다.','김진태','김영북스',34200,99,'2026-02-01'),
(189,6,9,'혼자 공부하는 바이브 코딩 with 클로드 코드','『혼자 공부하는 바이브 코딩 with 클로드 코드』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','조태호','한빛미디어',27000,67,'2025-12-16'),
(190,5,10,'빨모쌤의 라이브 영어회화(10만 부 기념 리커버 특별판)','『빨모쌤의 라이브 영어회화(10만 부 기념 리커버 특별판)』은 영어 실력을 체계적으로 다지기 위한 학습서로, 신용하의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','신용하','웅진지식하우스',19800,176,'2025-09-08'),
(191,3,11,'듀얼 브레인','『듀얼 브레인』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 이선 몰릭은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','이선 몰릭','상상스퀘어',18900,27,'2025-03-19'),
(192,5,12,'해커스 JLPT(일본어능력시험) N3 한권합격','『해커스 JLPT(일본어능력시험) N3 한권합격』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','해커스 JLPT연구소','해커스어학연구소',24300,176,'2025-01-24'),
(193,3,13,'너를 미워할 시간에 나를 사랑하기로 했다','『너를 미워할 시간에 나를 사랑하기로 했다』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 윤서진은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','윤서진','스몰빅라이프',16920,20,'2024-11-11'),
(194,4,14,'시한부','『시한부』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 시한부의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','백은별','바른북스',15120,17,'2024-01-23'),
(195,2,15,'오십에 읽는 주역','『오십에 읽는 주역』은 강기진의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','강기진','유노북스',15300,73,'2023-10-31'),
(196,1,16,'구의 증명(리커버판)','최진영의 『구의 증명(리커버판)』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 구의 증명이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','최진영','은행나무',10800,61,'2023-04-26'),
(197,3,17,'실전 차트 패턴 63','『실전 차트 패턴 63』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 윌리엄 자일러은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','윌리엄 자일러','이레미디어',16650,15,'2022-08-16'),
(198,1,18,'그리스인 조르바','니코스 카잔차키스의 『그리스인 조르바』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 그리스인 조르바이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','니코스 카잔차키스','열린책들',13320,169,'2009-12-20'),
(199,1,19,'4월의 어느 맑은 아침에 100퍼센트의 여자를 만나는 것에 대하여','무라카미 하루키의 『4월의 어느 맑은 아침에 100퍼센트의 여자를 만나는 것에 대하여』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 4월의 어느 맑은 아침에 100퍼센트의 여자를 만나는 것에 대하여이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','무라카미 하루키','문학사상',11700,49,'2009-11-30'),
(200,3,20,'역행자','『역행자』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 자청은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','자청','웅진지식하우스',17550,140,'2022-05-30'),
(201,10,21,'ONE PIECE magazine 21','『ONE PIECE magazine 21』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','集英社','集英社',17960,42,'2026-09-04'),
(202,1,22,'이상한 나라의 앨리스','루이스 캐럴의 『이상한 나라의 앨리스』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 이상한 나라의 앨리스이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','루이스 캐럴','문학동네',10800,131,'2026-04-10'),
(203,5,23,'2027 해커스경찰 조현 경찰학 기출문제집','『2027 해커스경찰 조현 경찰학 기출문제집』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','조현','해커스경찰',50400,181,'2026-04-06'),
