(206,3,26,'규칙파괴자','『규칙파괴자』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 데이비드 가드너은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','데이비드 가드너','국일증권경제연구소',22500,65,'2026-01-20'),
(207,2,27,'처음부터 끝까지 고백','『처음부터 끝까지 고백』은 주또(이주영)의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','주또(이주영)','시선과단상',15120,129,'2025-10-17'),
(208,7,28,'2026 에듀윌 산업안전기사 필기 한권끝장 이론편+기출문제편','『2026 에듀윌 산업안전기사 필기 한권끝장 이론편+기출문제편』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','최창률','에듀윌',34200,189,'2025-09-17'),
(209,6,29,'SQL 자격검정 실전문제','『SQL 자격검정 실전문제』은 컴퓨터와 데이터, 디지털 기술을 실제 활용 중심으로 익히게 하는 IT 분야 책이다. 기본 개념을 차근차근 설명하고 예제나 흐름을 통해 실무 감각을 키울 수 있게 구성되어 있다. 새로운 기술을 배우려는 독자에게 좋은 출발점이 된다.','한국데이터산업진흥원','한국데이터산업진흥원',18000,75,'2023-12-29'),
