(211,1,1,'희망','양귀자의 『희망』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 희망이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','양귀자','쓰다',17820,52,'2020-06-30'),
(212,1,2,'인간 실격','다자이 오사무의 『인간 실격』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 인간 실격이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','다자이 오사무','민음사',8100,165,'2012-04-10'),
(213,9,3,'클래식이 알고 싶다','『클래식이 알고 싶다』은 예술과 대중문화를 더 깊이 감상할 수 있도록 돕는 문화 교양서다. 작품이 만들어진 배경과 표현 방식, 창작자의 고민을 함께 다루어 보는 재미와 이해의 폭을 넓힌다.','안인모','위즈덤하우스',16200,165,'2019-10-23'),
(214,5,4,'김재우의 기본 동사 100','『김재우의 기본 동사 100』은 영어 실력을 체계적으로 다지기 위한 학습서로, 김재우의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','김재우','상상스퀘어',15400,193,'2025-12-10'),
