(216,4,6,'루미너스 오늘부터 데뷔합니다 5','『루미너스 오늘부터 데뷔합니다 5』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 루미너스 오늘부터 데뷔합니다 5의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','김영주','다산어린이',12600,51,'2026-04-08'),
(217,5,7,'2026 해커스공무원 실전동형모의고사 국어 2','『2026 해커스공무원 실전동형모의고사 국어 2』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','해커스 공무원시험연구소','해커스공무원',19800,89,'2026-04-03'),
(218,8,8,'국가는 무엇으로 싸우는가','『국가는 무엇으로 싸우는가』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','에드워드 피시먼','알에이치코리아',38700,37,'2026-03-20'),
(219,6,9,'이게 되네? 제미나이 완전 미친 활용법 81제','『이게 되네? 제미나이 완전 미친 활용법 81제』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','오힘찬','골든래빗(주)',21600,158,'2026-02-10'),
(220,5,10,'독끝 NCS 기본서: 독학으로 끝내는 공기업 NCS 통합기본서 (PSAT형+모듈형+피듈형)','『독끝 NCS 기본서: 독학으로 끝내는 공기업 NCS 통합기본서 (PSAT형+모듈형+피듈형)』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','길잡이 연구소 외','애드투',26100,16,'2026-02-02'),
(221,3,11,'존리의 부자되기 습관','『존리의 부자되기 습관』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 존 리은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','존 리','이든하우스',18000,89,'2026-01-28'),
(222,5,12,'만능문장으로 끝내는 토익스피킹 시계토끼 올인원 기본서 7일 완성','『만능문장으로 끝내는 토익스피킹 시계토끼 올인원 기본서 7일 완성』은 영어 실력을 체계적으로 다지기 위한 학습서로, 시계토끼제니쌤(차지영)의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','시계토끼제니쌤(차지영)','시계토끼',19980,157,'2025-12-10'),
(223,2,13,'손자병법','『손자병법』은 손자의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','손자','현대지성',11700,183,'2025-10-14'),
(224,5,14,'2026 해커스군무원 신민숙 쉬운국어 문법·어휘 한 권으로 끝','『2026 해커스군무원 신민숙 쉬운국어 문법·어휘 한 권으로 끝』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','신민숙','해커스군무원',17100,106,'2025-08-26'),
(225,3,15,'현명한 투자자','『현명한 투자자』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 벤저민 그레이엄은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','벤저민 그레이엄','국일증권경제연구소',25200,111,'2025-06-02'),
(226,5,16,'서아쌤의 토익 비밀과외','『서아쌤의 토익 비밀과외』은 영어 실력을 체계적으로 다지기 위한 학습서로, 최서아 외의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','최서아 외','시원스쿨닷컴',16920,193,'2024-11-27'),
(227,2,17,'팩트풀니스(50만 부 뉴에디션)','『팩트풀니스(50만 부 뉴에디션)』은 한스 로슬링 외의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','한스 로슬링 외','김영사',21420,60,'2024-09-01'),
(228,3,18,'불변의 법칙','『불변의 법칙』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 모건 하우절은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','모건 하우절','서삼독',22500,29,'2024-02-28'),
(229,2,19,'눈물 한 방울','『눈물 한 방울』은 이어령의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','이어령','김영사',14220,161,'2022-06-30'),
(230,1,20,'오늘 밤, 세계에서 이 사랑이 사라진다 해도','이치조 미사키의 『오늘 밤, 세계에서 이 사랑이 사라진다 해도』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 오늘 밤, 세계에서 이 사랑이 사라진다 해도이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','이치조 미사키','모모',12600,186,'2021-06-28'),
(231,1,21,'나는 소망한다 내게 금지된 것을','양귀자의 『나는 소망한다 내게 금지된 것을』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 나는 소망한다 내게 금지된 것을이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','양귀자','쓰다',13500,170,'2019-04-20'),
(232,12,22,'삐뽀삐뽀 119 이유식','『삐뽀삐뽀 119 이유식』은 취미와 실용 활동을 즐겁게 시작할 수 있도록 돕는 책이다. 필요한 준비 과정과 방법을 구체적으로 안내해 처음 접하는 독자도 따라가기 쉽다. 일상에 새로운 재미와 활력을 더하고 싶은 사람에게 어울린다.','하정훈','유니책방',17010,72,'2017-12-01'),
(233,2,23,'The Daily Stoic','『The Daily Stoic』은 Ryan Holiday의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','Ryan Holiday','Portfolio',10900,36,'2016-10-18'),
(234,1,24,'달과 6펜스','서머싯 몸의 『달과 6펜스』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 달과 6펜스이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','서머싯 몸','민음사',9000,188,'2000-06-20'),
(235,8,25,'손절사회','『손절사회』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','이승연','어크로스',18900,87,'2026-04-16'),
(236,5,26,'2026 해커스공무원 실전동형모의고사 한국사 2 16회분','『2026 해커스공무원 실전동형모의고사 한국사 2 16회분』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','해커스 공무원시험연구소','해커스공무원',17100,185,'2026-04-03'),
(237,4,27,'슈뻘맨의 슈퍼 상식 월드컵 5: 최강의 귀신과 요괴','『슈뻘맨의 슈퍼 상식 월드컵 5: 최강의 귀신과 요괴』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 슈뻘맨의 슈퍼 상식 월드컵 5: 최강의 귀신과 요괴의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','슈뻘맨','주니어김영사',13500,163,'2026-03-26'),
(238,11,28,'살찌지 않는 몸','『살찌지 않는 몸』은 가정과 생활, 육아와 건강에 필요한 실용적인 조언을 담은 책이다. 일상에서 바로 적용할 수 있는 방법을 중심으로 구성되어 있어 부담 없이 읽을 수 있다. 더 안정적인 생활 습관과 관계를 만들고 싶은 독자에게 도움이 된다.','우창윤','웅진지식하우스',17820,40,'2026-03-13'),
(239,4,29,'마음의 주인은 언제나 나야','『마음의 주인은 언제나 나야』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 마음의 주인은 언제나 나야의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','손원우','페이지2북스',16920,154,'2026-03-11'),
(240,5,30,'2026 민준호 행정법 실전동형 모의고사 최최개사기','『2026 민준호 행정법 실전동형 모의고사 최최개사기』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','민준호','호인북스',19800,20,'2026-01-30'),
(241,10,1,'원피스 113: 로키탄생','『원피스 113: 로키탄생』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Eiichiro Oda','대원씨아이',5850,98,'2026-01-30'),
(242,5,2,'2026 단기 합격 해커스공기업 NCS 통합 기본서(모듈형+피듈형+PSAT형+모의고사 6회분)','『2026 단기 합격 해커스공기업 NCS 통합 기본서(모듈형+피듈형+PSAT형+모의고사 6회분)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','윤종혁 외','해커스잡',24300,146,'2026-01-02'),
(243,5,3,'서아쌤의 토익 비밀과외 기출 VOCA','『서아쌤의 토익 비밀과외 기출 VOCA』은 영어 실력을 체계적으로 다지기 위한 학습서로, 시원스쿨어학연구소의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','시원스쿨어학연구소','시원스쿨닷컴',13320,119,'2025-11-25'),
(244,7,4,'2026 에듀윌 건설안전기사 필기 기출문제집','『2026 에듀윌 건설안전기사 필기 기출문제집』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','김충민 외','에듀윌',27900,179,'2025-10-30'),
(245,3,5,'마흔의 기술','『마흔의 기술』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 이호선은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','이호선','오아시스',16200,104,'2025-10-20'),
(246,5,6,'서아쌤의 토익 비밀과외 START','『서아쌤의 토익 비밀과외 START』은 영어 실력을 체계적으로 다지기 위한 학습서로, 최서아 외의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','최서아 외','시원스쿨닷컴',15120,27,'2025-06-17'),
(247,3,7,'제로 투 원(10주년 기념판)','『제로 투 원(10주년 기념판)』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 피터 틸 외은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','피터 틸 외','한국경제신문',16200,139,'2025-04-18'),
(248,5,8,'처음 JLPT N4·N5 단숨에 합격하기','『처음 JLPT N4·N5 단숨에 합격하기』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','시원스쿨어학연구소','시원스쿨닷컴',15120,175,'2024-12-20'),
(249,2,9,'하늘과 바람과 별과 시(초판본)','『하늘과 바람과 별과 시(초판본)』은 윤동주의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','윤동주','더스토리',2700,97,'2024-12-15'),
(250,2,10,'아비투스(양장특별판)','『아비투스(양장특별판)』은 도리스 메르틴의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','도리스 메르틴','다산초당',19800,13,'2023-03-24'),
(251,5,11,'해커스공기업 NCS 피듈형(모듈+피셋) 통합 봉투모의고사 7회 (온라인 1회 포함)','『해커스공기업 NCS 피듈형(모듈+피셋) 통합 봉투모의고사 7회 (온라인 1회 포함)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','해커스 취업교육연구소','해커스공기업',16110,117,'2023-01-03'),
(252,5,12,'ETS 토익기출 파트별 VOCA','『ETS 토익기출 파트별 VOCA』은 영어 실력을 체계적으로 다지기 위한 학습서로, ETS의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','ETS','YBM',11700,135,'2022-12-23'),
(253,12,13,'아이주도 이유식 유아식 매뉴얼 세트','『아이주도 이유식 유아식 매뉴얼 세트』은 취미와 실용 활동을 즐겁게 시작할 수 있도록 돕는 책이다. 필요한 준비 과정과 방법을 구체적으로 안내해 처음 접하는 독자도 따라가기 쉽다. 일상에 새로운 재미와 활력을 더하고 싶은 사람에게 어울린다.','BLW 연구소','아퍼블리싱',21150,37,'2021-08-31'),
(254,1,14,'홍학의 자리(리커버판)','정해연의 『홍학의 자리(리커버판)』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 홍학의 자리이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','정해연','엘릭시르',12600,120,'2021-07-26'),
(255,3,15,'자본주의','『자본주의』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. EBS 자본주의 제작팀은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','EBS 자본주의 제작팀','가나출판사',19800,102,'2013-09-27'),
(256,1,16,'면도날','서머싯 몸의 『면도날』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 면도날이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','서머싯 몸','민음사',13500,172,'2009-06-30'),
(257,4,17,'어린 임금의 눈물','『어린 임금의 눈물』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 어린 임금의 눈물의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','이규희','파랑새어린이',13500,127,'2004-02-27'),
(258,7,18,'궤도의 과학 허세','『궤도의 과학 허세』은 과학과 기술의 원리를 이해하기 쉽게 풀어낸 교양서다. 복잡하게 느껴지는 개념을 생활 속 사례와 연결해 설명하며, 세상을 바라보는 과학적 시선을 넓혀 준다. 호기심을 지식으로 발전시키고 싶은 독자에게 어울린다.','궤도','동아시아',17010,191,'2018-12-12'),
(259,4,19,'웃기는 우주과학 코스모스웩 2','『웃기는 우주과학 코스모스웩 2』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 웃기는 우주과학 코스모스웩 2의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','코스모스웩','서울문화사',14220,49,'2026-04-30'),
(260,10,20,'K-9 경시청 공안부 공안제9과 이능력 대책반 1(특별판)','『K-9 경시청 공안부 공안제9과 이능력 대책반 1(특별판)』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Tetsuya Okuyama','대원씨아이',13500,121,'2026-04-30'),
(261,3,21,'AI 교양서: 인간은 어떻게 인공지능을 진화시키는가','『AI 교양서: 인간은 어떻게 인공지능을 진화시키는가』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','이영호 외','비제이퍼블릭',24300,55,'2026-04-20'),
(262,14,22,'EBS 중급영어회화 파워잉글리시(라디오)(2026년 5월호)','『EBS 중급영어회화 파워잉글리시(라디오)(2026년 5월호)』은 영어 실력을 체계적으로 다지기 위한 학습서로, 크리스틴 조의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','크리스틴 조','동아출판',8550,197,'2026-04-16'),
(263,4,23,'끝까지 해 보자, 때밀이 장갑!','『끝까지 해 보자, 때밀이 장갑!』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 끝까지 해 보자, 때밀이 장갑!의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','유설화','책읽는곰',13500,143,'2026-04-15'),
(264,14,24,'청소년매일성경(2026년 5/6월호)','『청소년매일성경(2026년 5/6월호)』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','성서유니온 편집부','성서유니온',4270,176,'2026-04-07'),
(265,4,25,'설민석의 그리스 로마 신화 대모험 15: 사랑의 여신 아프로디테','『설민석의 그리스 로마 신화 대모험 15: 사랑의 여신 아프로디테』은 어린이와 청소년이 흥미로운 이야기 속에서 지식과 상상력을 함께 키울 수 있도록 구성된 책이다. 익숙한 캐릭터와 사건 전개를 따라가다 보면 역사, 신화, 과학 같은 주제를 자연스럽게 이해하게 된다. 재미와 학습을 함께 잡고 싶은 독자에게 잘 맞는다.','설민석 외','단꿈아이',13500,79,'2026-04-06'),
(266,10,26,'반딧불이의 혼례 10','『반딧불이의 혼례 10』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Oreco TACHIBANA','서울미디어코믹스(서울문화사)',7650,167,'2026-04-03'),
(267,3,27,'다녀왔습니다!: 실리콘밸리, 워싱턴 D.C. 그리고 텍사스','『다녀왔습니다!: 실리콘밸리, 워싱턴 D.C. 그리고 텍사스』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 토스증권 리서치센터은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','토스증권 리서치센터','비즈니스북스',18000,147,'2026-03-23'),
(268,5,28,'2026 문동균 한국사 D-30 문단속 모의고사','『2026 문동균 한국사 D-30 문단속 모의고사』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','문동균','에스티유니타스',14400,133,'2026-02-27'),
(269,5,29,'전수환 공기업 경영학 개념심화','『전수환 공기업 경영학 개념심화』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','전수환','밀더북',42300,129,'2026-01-26'),
(270,4,30,'읽으면서 바로 써먹는 어린이 공포의 수학 퍼즐 2','『읽으면서 바로 써먹는 어린이 공포의 수학 퍼즐 2』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 읽으면서 바로 써먹는 어린이 공포의 수학 퍼즐 2의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','한날','파란정원',11700,121,'2025-12-15'),
(271,2,1,'월든(완결판)(리커버:K)','『월든(완결판)(리커버:K)』은 헨리 데이빗 소로우의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','헨리 데이빗 소로우','은행나무',11700,197,'2025-10-27'),
(272,5,2,'2026 해커스공무원 3분의 1로 줄여 쓴 김대현 행정법총론 기본서','『2026 해커스공무원 3분의 1로 줄여 쓴 김대현 행정법총론 기본서』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','김대현','해커스공무원',26100,161,'2025-06-02'),
(273,4,3,'질문으로 답을 찾는 인공지능 윤리 수업','『질문으로 답을 찾는 인공지능 윤리 수업』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','박형빈','한언',18900,78,'2025-04-15'),
(274,3,4,'사모펀드 투자와 경영의 비밀','『사모펀드 투자와 경영의 비밀』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 김태엽은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','김태엽','세이코리아',24300,92,'2024-10-25'),
(275,5,5,'영어로 문장 만들기 훈련 1차 임계점','『영어로 문장 만들기 훈련 1차 임계점』은 영어 실력을 체계적으로 다지기 위한 학습서로, 유은하의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','유은하','사람in',19800,72,'2024-07-15'),
(276,4,6,'기억 전달자','『기억 전달자』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 기억 전달자의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','로이스 로리','비룡소',14400,32,'2024-03-25'),
(277,11,7,'삐뽀삐뽀 119 소아과','『삐뽀삐뽀 119 소아과』은 가정과 생활, 육아와 건강에 필요한 실용적인 조언을 담은 책이다. 일상에서 바로 적용할 수 있는 방법을 중심으로 구성되어 있어 부담 없이 읽을 수 있다. 더 안정적인 생활 습관과 관계를 만들고 싶은 독자에게 도움이 된다.','하정훈','유니책방',26820,81,'2024-01-05'),
(278,3,8,'처음부터 시작하는 주식투자 단타전략','『처음부터 시작하는 주식투자 단타전략』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 홍인기은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','홍인기','길벗',18900,125,'2023-12-22'),
(279,1,9,'율리시스 1','제임스 조이스의 『율리시스 1』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 율리시스 1이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','제임스 조이스','문학동네',22500,72,'2023-12-08'),
(280,2,10,'사피엔스','『사피엔스』은 유발 하라리의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','유발 하라리','김영사',24120,128,'2023-04-01'),
(281,1,11,'왜 나는 너를 사랑하는가(70만 부 기념 리커버)','알랭 드 보통의 『왜 나는 너를 사랑하는가(70만 부 기념 리커버)』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 왜 나는 너를 사랑하는가이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','알랭 드 보통','청미래',12600,155,'2022-11-10'),
(282,2,12,'잘했고 잘하고 있고 잘될 것이다(50만부 기념)','『잘했고 잘하고 있고 잘될 것이다(50만부 기념)』은 정영욱의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','정영욱','부크럼',16200,166,'2022-10-28'),
(283,9,13,'서양미술사','『서양미술사』은 예술과 문화의 세계를 더 가까이 이해하도록 돕는 책이다. 작품과 창작자의 배경을 함께 살펴보며 단순한 감상을 넘어 표현 방식과 시대적 의미까지 생각하게 한다. 문화 콘텐츠를 깊이 있게 즐기고 싶은 독자에게 어울린다.','E. H. 곰브리치','예경',47700,181,'2017-05-30'),
(284,1,14,'픽션들','호르헤 루이스 보르헤스의 『픽션들』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 픽션들이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','호르헤 루이스 보르헤스','민음사',9900,107,'2011-10-21'),
(285,1,15,'설국','가와바타 야스나리의 『설국』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 설국이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','가와바타 야스나리','민음사',7200,96,'2009-01-20'),
(286,1,16,'모순','양귀자의 장편소설 『모순』은 평범해 보이는 가족과 사랑의 관계 속에서 삶이 품은 아이러니를 섬세하게 포착한 작품이다. 주인공 안진진이 주변 인물들의 선택을 바라보며 성장하는 과정이 담겨 있으며, 행복과 불행이 맞물린 인생의 복잡한 얼굴을 깊이 생각하게 한다.','양귀자','쓰다',11700,95,'2013-04-01'),
(287,11,17,'오늘도 교실에서 아이의 마음을 읽었습니다','『오늘도 교실에서 아이의 마음을 읽었습니다』은 가정과 생활, 육아와 건강에 필요한 실용적인 조언을 담은 책이다. 일상에서 바로 적용할 수 있는 방법을 중심으로 구성되어 있어 부담 없이 읽을 수 있다. 더 안정적인 생활 습관과 관계를 만들고 싶은 독자에게 도움이 된다.','하민경','미다스북스',16650,136,'2026-04-21'),
(288,12,18,'생선 숙성의 기술','『생선 숙성의 기술』은 취미와 실용 활동을 즐겁게 시작할 수 있도록 돕는 책이다. 필요한 준비 과정과 방법을 구체적으로 안내해 처음 접하는 독자도 따라가기 쉽다. 일상에 새로운 재미와 활력을 더하고 싶은 사람에게 어울린다.','김상돈','그린쿡',27000,93,'2026-04-20'),
(289,7,19,'Beyond: AI가 이끄는 인지 혁명','『Beyond: AI가 이끄는 인지 혁명』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','박종성','이든서재',19800,56,'2026-04-20'),
(290,14,20,'EBS 초급 일본어(2026년 5월호)','『EBS 초급 일본어(2026년 5월호)』은 정해진 기간 동안 읽기 좋은 묵상과 정보, 다양한 읽을거리를 담은 잡지형 도서다. 짧은 글을 꾸준히 읽으며 생활의 리듬을 잡고, 필요한 내용을 부담 없이 찾아볼 수 있도록 구성되어 있다.','이은미','동아출판',7600,134,'2026-04-16'),
(291,5,21,'2026 How To Pass 실전 모의고사 문제편+해설편 세트','『2026 How To Pass 실전 모의고사 문제편+해설편 세트』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','이경범','씨엘웍스',28800,64,'2026-04-15'),
(292,2,22,'너라는 우주','『너라는 우주』은 그림에다의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','그림에다','길벗',17820,100,'2026-04-15'),
(293,1,23,'GV 빌런 고태경','정대건의 『GV 빌런 고태경』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 GV 빌런 고태경이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','정대건','문학동네',16650,76,'2026-04-15'),
(294,6,24,'세컨드 브레인은 옵시디언 with 클로드 코드','『세컨드 브레인은 옵시디언 with 클로드 코드』은 컴퓨터와 데이터, 디지털 기술을 실제 활용 중심으로 익히게 하는 IT 분야 책이다. 기본 개념을 차근차근 설명하고 예제나 흐름을 통해 실무 감각을 키울 수 있게 구성되어 있다. 새로운 기술을 배우려는 독자에게 좋은 출발점이 된다.','시안','골든래빗(주)',22500,97,'2026-04-13'),
(295,5,25,'영어 단어의 톤과 의미 차이','『영어 단어의 톤과 의미 차이』은 영어 실력을 체계적으로 다지기 위한 학습서로, LJ쌤(이진)의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','LJ쌤(이진)','사람in',22500,81,'2026-04-09'),
(296,3,26,'미스터 나카모토: 비트코인의 창시자','『미스터 나카모토: 비트코인의 창시자』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 벤저민 월리스은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','벤저민 월리스','북플레저',22500,162,'2026-04-08'),
(297,4,27,'교과서 속 인물에게 배우는 최소한의 개념 수업','『교과서 속 인물에게 배우는 최소한의 개념 수업』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 교과서 속 인물에게 배우는 최소한의 개념 수업의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','박성경 외','미디어숲',16920,189,'2026-04-08'),
(298,5,28,'2026 투자자산운용사 출제동형 PLUS 최신 9회분(44회)','『2026 투자자산운용사 출제동형 PLUS 최신 9회분(44회)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','유창호','시대고시기획',31500,80,'2026-04-03'),
(299,7,29,'모든 것은 결정되어 있다','『모든 것은 결정되어 있다』은 과학과 기술의 원리를 이해하기 쉽게 풀어낸 교양서다. 복잡하게 느껴지는 개념을 생활 속 사례와 연결해 설명하며, 세상을 바라보는 과학적 시선을 넓혀 준다. 호기심을 지식으로 발전시키고 싶은 독자에게 어울린다.','로버트 M. 새폴스키','문학동네',38700,152,'2026-03-30'),
(300,3,30,'트라이브즈','『트라이브즈』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 세스 고딘은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','세스 고딘','필름(Feelm)',20250,12,'2026-03-25');
