INSERT INTO [dbo].[books] (b_no, c_no, l_no, b_name, b_info, b_writer, b_publisher, b_price, b_stock, b_date) VALUES (301,4,1,'소맥거핀의 인체 친구들 6: 삐삐삐삐 심장 풀가동 중!','『소맥거핀의 인체 친구들 6: 삐삐삐삐 심장 풀가동 중!』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 소맥거핀의 인체 친구들 6: 삐삐삐삐 심장 풀가동 중!의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','소맥거핀','위즈덤하우스',13320,142,'2026-03-20'),
(302,1,2,'참을 수 없는 존재의 가벼움(리커버판)','밀란 쿤데라의 『참을 수 없는 존재의 가벼움(리커버판)』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 참을 수 없는 존재의 가벼움이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','밀란 쿤데라','민음사',15300,58,'2026-03-10'),
(303,2,3,'다크 심리학: 연애의 법칙','『다크 심리학: 연애의 법칙』은 다크 마인드의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','다크 마인드','다크마인드북스',17820,31,'2026-01-28'),
(304,5,4,'2026 해커스경찰 갓대환 형사법 기본서 1: 형법','『2026 해커스경찰 갓대환 형사법 기본서 1: 형법』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','김대환','해커스경찰',42300,71,'2026-01-09'),
(305,3,5,'운명을 보는 기술','『운명을 보는 기술』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 박성준은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','박성준','페이지2북스',16920,194,'2025-10-31'),
(306,5,6,'2026 심슨 문법 300제','『2026 심슨 문법 300제』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','심우철','에스티유니타스',14400,114,'2025-10-27'),
(307,5,7,'2026 황철곤 행정학 기출문제집 세트','『2026 황철곤 행정학 기출문제집 세트』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','황철곤','넥스트스터디',41400,135,'2025-08-25'),
(308,5,8,'2026 문동균 한국사 기출은 문동균','『2026 문동균 한국사 기출은 문동균』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','문동균','에스티유니타스',27000,152,'2025-08-13'),
(309,5,9,'2026 해커스군무원 신민숙 쉬운국어 문학·독해 한 권으로 끝','『2026 해커스군무원 신민숙 쉬운국어 문학·독해 한 권으로 끝』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','신민숙','해커스군무원',17100,71,'2025-08-11'),
(310,10,10,'주술회전 30: 앞으로','『주술회전 30: 앞으로』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Gege Akutami','서울미디어코믹스(서울문화사)',5400,186,'2025-08-01'),
(311,10,11,'스티커','『스티커』는 초록색 표지와 인물 일러스트가 돋보이는 스티커북이다. 귀여운 장식 요소와 감각적인 디자인이 담겨 있어 표지처럼 꾸미기와 소장용으로 활용하기 좋다. 캐릭터 감성과 스티커 구성의 재미를 함께 느낄 수 있는 책이다.','편집부','스티커북',7200,100,'2026-05-13'),
(312,4,12,'윤슬의 바다','『윤슬의 바다』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 윤슬의 바다의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','백은별','바른북스',13500,175,'2025-05-31'),
(313,5,13,'독끝 NCS 문제해결·자원관리능력 460제(공기업 NCS/대기업 인적성 대비 독학으로 끝내는 문제해결·자원관리 PSAT)','『독끝 NCS 문제해결·자원관리능력 460제(공기업 NCS/대기업 인적성 대비 독학으로 끝내는 문제해결·자원관리 PSAT)』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','길잡이연구소 외','애드투',29700,192,'2025-03-01'),
(314,2,14,'큰별쌤 최태성의 별별한국사 7일의 기적 한국사능력검정시험 심화(1, 2, 3급)(2026)','『큰별쌤 최태성의 별별한국사 7일의 기적 한국사능력검정시험 심화(1, 2, 3급)(2026)』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','최태성','이투스북',14850,135,'2024-04-03'),
(315,12,15,'뿐이 토핑 이유식','『뿐이 토핑 이유식』은 취미와 실용 활동을 즐겁게 시작할 수 있도록 돕는 책이다. 필요한 준비 과정과 방법을 구체적으로 안내해 처음 접하는 독자도 따라가기 쉽다. 일상에 새로운 재미와 활력을 더하고 싶은 사람에게 어울린다.','정주희','서사원',26820,124,'2024-02-26'),
(316,3,16,'더 시스템(THE SYSTEM)','『더 시스템(THE SYSTEM)』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 스콧 애덤스은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','스콧 애덤스','베리북',16200,14,'2024-01-29'),
(317,5,17,'김재우의 영어회화 100','『김재우의 영어회화 100』은 영어 실력을 체계적으로 다지기 위한 학습서로, 김재우의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','김재우','상상스퀘어',19800,33,'2023-07-05'),
(318,4,18,'세포부터 나일까? 언제부터 나일까?','『세포부터 나일까? 언제부터 나일까?』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 세포부터 나일까? 언제부터 나일까?의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','이고은','창비',11700,85,'2023-04-07'),
(319,3,19,'세이노의 가르침','『세이노의 가르침』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 세이노(SayNo)은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','세이노(SayNo)','데이원',6480,66,'2023-03-02'),
(320,5,20,'일본어 무작정 따라하기(완전판)','『일본어 무작정 따라하기(완전판)』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','후지이 아사리','길벗이지톡',23400,113,'2022-08-05'),
(321,4,21,'죽이고 싶은 아이','『죽이고 싶은 아이』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 죽이고 싶은 아이의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','이꽃님','우리학교',11250,187,'2021-06-07'),
(322,2,22,'소년과 두더지와 여우와 말','『소년과 두더지와 여우와 말』은 찰리 맥커시의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','찰리 맥커시','상상의힘',19800,72,'2020-04-20'),
(323,4,23,'담을 넘은 아이','『담을 넘은 아이』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 담을 넘은 아이의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','김정민','비룡소',12600,88,'2019-07-30'),
(324,13,24,'스크루테이프의 편지','『스크루테이프의 편지』은 믿음과 삶의 의미를 차분히 돌아보게 하는 종교 분야 도서다. 마음을 다잡는 문장과 성찰의 흐름을 통해 내면의 평안과 실천의 방향을 생각하게 한다.','C. S. 루이스','홍성사',11700,179,'2018-11-15'),
(325,4,25,'귀찮아, 법 없이 살면 안 될까?','『귀찮아, 법 없이 살면 안 될까?』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 귀찮아, 법 없이 살면 안 될까?의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','곽한영','나무를심는사람들',11700,158,'2017-09-25'),
(326,5,26,'Basic Grammar in Use Student''s Book with Answers and Interactive eBook','『Basic Grammar in Use Student''s Book with Answers and Interactive eBook』은 영어 실력을 체계적으로 다지기 위한 학습서로, Raymond Murphy 외의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','Raymond Murphy 외','Cambridge University Press',33300,104,'2017-09-21'),
(327,1,27,'천년의 사랑','양귀자의 『천년의 사랑』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 천년의 사랑이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','양귀자','쓰다',13500,131,'2013-04-20'),
(328,1,28,'두근 두근 내 인생','김애란의 『두근 두근 내 인생』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 두근 두근 내 인생이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','김애란','창비',14400,151,'2011-06-20'),
(329,1,29,'수레바퀴 아래서','헤르만 헤세의 『수레바퀴 아래서』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 수레바퀴 아래서이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','헤르만 헤세','민음사',7200,145,'2009-01-20'),
(330,1,30,'1984','조지 오웰의 『1984』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 1984이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','조지 오웰','민음사',9900,98,'2007-03-30'),
(331,14,1,'엘르(2026년 5월호)','『엘르(2026년 5월호)』은 정해진 기간 동안 읽기 좋은 묵상과 정보, 다양한 읽을거리를 담은 잡지형 도서다. 짧은 글을 꾸준히 읽으며 생활의 리듬을 잡고, 필요한 내용을 부담 없이 찾아볼 수 있도록 구성되어 있다.','허스트중앙 편집부','허스트중앙',7600,118,'2026-04-25'),
(332,2,2,'경전의 탄생','『경전의 탄생』은 카렌 암스트롱의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','카렌 암스트롱','교양인',37800,200,'2026-04-15'),
(333,5,3,'2026 오정화 세법: 지방세법 세트','『2026 오정화 세법: 지방세법 세트』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','오정화','올에듀케이션',42300,150,'2026-04-13'),
(334,5,4,'2026 황철곤 행정학 실전동형 모의고사 2','『2026 황철곤 행정학 실전동형 모의고사 2』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','황철곤','넥스트스터디',14400,94,'2026-04-10'),
(335,3,5,'누구나 혼자 서는 순간이 온다','『누구나 혼자 서는 순간이 온다』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 김나이은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','김나이','북스톤',16200,100,'2026-04-09'),
(336,3,6,'휘둘리지 않는 법','『휘둘리지 않는 법』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 대니얼 치디악은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','대니얼 치디악','웅진지식하우스',17010,189,'2026-04-08'),
(337,3,7,'김민식의 내 몸을 바꾸는 평생 루틴','『김민식의 내 몸을 바꾸는 평생 루틴』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 김민식은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','김민식','중앙북스',18000,126,'2026-04-05'),
(338,5,8,'2026 해커스경찰 갓대환 형사법 핵심요약집 형법','『2026 해커스경찰 갓대환 형사법 핵심요약집 형법』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','김대환','해커스경찰',40500,79,'2026-04-03'),
(339,3,9,'3040 부린이 처음 부동산 투자','『3040 부린이 처음 부동산 투자』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 김학렬(빠숑)은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','김학렬(빠숑)','포르체',21600,88,'2026-04-01'),
(340,5,10,'JLPT(일본어능력시험) 한권으로 끝내기 N1','『JLPT(일본어능력시험) 한권으로 끝내기 N1』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','이치우 외','다락원',25200,74,'2026-03-30'),
(341,13,11,'읽는 기도(영문판)','『읽는 기도(영문판)』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','무명의 기도자','더하트',900,69,'2026-03-25'),
(342,2,12,'오버씽킹','『오버씽킹』은 벳시 홈버그의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','벳시 홈버그','웅진지식하우스',17100,40,'2026-03-19'),
(343,5,13,'2026 시대에듀 투자자산운용사 한권으로 끝내기 ver 17','『2026 시대에듀 투자자산운용사 한권으로 끝내기 ver 17』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','유창호','시대에듀',34200,194,'2026-03-05'),
(344,10,14,'스파이 패밀리 16','『스파이 패밀리 16』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','Tatsuya Endo','학산문화사',5400,59,'2026-03-05'),
(345,3,15,'미라클 모닝 After 50','『미라클 모닝 After 50』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 할 엘로드 외은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','할 엘로드 외','필름(Feelm)',19800,90,'2026-03-04'),
(346,5,16,'2026 써니 행정법총론 실전동형 모의고사','『2026 써니 행정법총론 실전동형 모의고사』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','박준철','에스티유니타스',14400,40,'2026-02-04'),
(347,1,17,'눈과 돌멩이(제49회 이상문학상 작품집 2026년)','위수정 외의 『눈과 돌멩이(제49회 이상문학상 작품집 2026년)』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 눈과 돌멩이이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','위수정 외','다산책방',16200,200,'2026-01-23'),
(348,5,18,'2026 문동균 한국사 문단속 적중 최종병기 Final 모의고사','『2026 문동균 한국사 문단속 적중 최종병기 Final 모의고사』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','문동균','에스티유니타스',14400,147,'2026-01-22'),
(349,7,19,'뇌는 어떻게 나를 조종하는가','『뇌는 어떻게 나를 조종하는가』은 과학과 기술의 원리를 이해하기 쉽게 풀어낸 교양서다. 복잡하게 느껴지는 개념을 생활 속 사례와 연결해 설명하며, 세상을 바라보는 과학적 시선을 넓혀 준다. 호기심을 지식으로 발전시키고 싶은 독자에게 어울린다.','크리스 나이바우어','클랩북스',16920,186,'2026-01-21'),
(350,1,20,'쥬디 할머니','박완서의 『쥬디 할머니』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 쥬디 할머니이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','박완서','문학동네',16650,57,'2026-01-20'),
(351,4,21,'웃기는 우주과학 코스모스웩 1','『웃기는 우주과학 코스모스웩 1』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 웃기는 우주과학 코스모스웩 1의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','코스모스웩','서울문화사',14220,59,'2025-11-28'),
(352,5,22,'한권 한달 완성 일본어 말하기 Lv 1','『한권 한달 완성 일본어 말하기 Lv 1』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','시원스쿨어학연구소','시원스쿨닷컴',15120,65,'2025-11-27'),
(353,5,23,'2026 단계별 기출 핵심지문 박철한 경찰헌법 OX 시즌4','『2026 단계별 기출 핵심지문 박철한 경찰헌법 OX 시즌4』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','박철한','법률저널',34200,199,'2025-10-02'),
(354,11,24,'뇌가 멈추기 전에','『뇌가 멈추기 전에』은 가정과 생활, 육아와 건강에 필요한 실용적인 조언을 담은 책이다. 일상에서 바로 적용할 수 있는 방법을 중심으로 구성되어 있어 부담 없이 읽을 수 있다. 더 안정적인 생활 습관과 관계를 만들고 싶은 독자에게 도움이 된다.','이승훈','21세기북스',17910,133,'2025-07-02'),
(355,1,25,'변신(초판본)(1916년 오리지널 초판본 표지디자인)','『변신(초판본)(1916년 오리지널 초판본 표지디자인)』은 예술과 문화의 세계를 더 가까이 이해하도록 돕는 책이다. 작품과 창작자의 배경을 함께 살펴보며 단순한 감상을 넘어 표현 방식과 시대적 의미까지 생각하게 한다. 문화 콘텐츠를 깊이 있게 즐기고 싶은 독자에게 어울린다.','프란츠 카프카','더스토리',2690,80,'2025-02-28'),
(356,1,26,'킬리만자로의 눈','어니스트 헤밍웨이의 『킬리만자로의 눈』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 킬리만자로의 눈이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','어니스트 헤밍웨이','문학동네',12600,195,'2025-01-15'),
(357,1,27,'천 개의 파랑','천선란의 『천 개의 파랑』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 천 개의 파랑이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','천선란','허블',12600,100,'2020-08-19'),
(358,4,28,'맛집에서 만난 세계지리 수업','『맛집에서 만난 세계지리 수업』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 맛집에서 만난 세계지리 수업의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','남원상','서해문집',15120,144,'2024-09-10'),
(359,5,29,'해커스 토익 RC Reading(리딩) 기본서','『해커스 토익 RC Reading(리딩) 기본서』은 영어 실력을 체계적으로 다지기 위한 학습서로, David Cho의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','David Cho','해커스어학연구소',16920,162,'2024-08-19'),
(360,5,30,'해커스 JLPT(일본어능력시험)기출단어장 N5-N3','『해커스 JLPT(일본어능력시험)기출단어장 N5-N3』은 시험을 앞둔 독자가 빠르게 약점을 점검하고 실전 감각을 끌어올릴 수 있도록 만든 수험서다. 출제 흐름에 맞춘 핵심 정리와 문제 풀이 중심 구성이 특징이며, 제한 시간 안에서 정확하게 답을 찾는 연습을 돕는다.','해커스 JLPT 연구소','해커스어학연구소',12510,82,'2024-07-08'),
(361,1,1,'사에즈리 도서관의 와루츠 씨','코교쿠 이즈키의 『사에즈리 도서관의 와루츠 씨』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 사에즈리 도서관의 와루츠 씨이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','코교쿠 이즈키','알토북스',16020,35,'2024-05-10'),
(362,4,2,'청소년을 위한 경제의 역사','『청소년을 위한 경제의 역사』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 니콜라우스 피퍼은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','니콜라우스 피퍼','비룡소',15300,59,'2024-01-30'),
(363,4,3,'여름을 한 입 베어 물었더니','『여름을 한 입 베어 물었더니』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 여름을 한 입 베어 물었더니의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','이꽃님','문학동네',12150,85,'2023-08-18'),
(364,2,4,'미움받을 용기(200만 부 기념 스페셜 에디션)','『미움받을 용기(200만 부 기념 스페셜 에디션)』은 기시미 이치로 외의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','기시미 이치로 외','인플루엔셜',14310,68,'2022-12-28'),
(365,3,5,'부자 아빠 가난한 아빠 1(20주년 특별 기념판)','『부자 아빠 가난한 아빠 1(20주년 특별 기념판)』은 돈과 투자, 자산을 바라보는 관점을 현실적인 사례와 함께 풀어낸 책이다. 로버트 기요사키은 시장의 흐름을 무작정 따라가기보다 자신의 기준을 세우고 위험을 관리하는 태도를 강조한다. 재테크를 처음 시작하는 독자부터 투자 습관을 점검하려는 독자까지 참고하기 좋다.','로버트 기요사키','민음인',15300,102,'2022-10-28'),
(366,4,6,'기발하고 신기한 수학의 재미(하편)','『기발하고 신기한 수학의 재미(하편)』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 기발하고 신기한 수학의 재미의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','천융밍','미디어숲',16020,55,'2022-07-20'),
(367,4,7,'나를 지키는 최소한의 법 이야기','『나를 지키는 최소한의 법 이야기』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 나를 지키는 최소한의 법 이야기의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','양지열','자음과모음',15120,87,'2022-01-28'),
(368,11,8,'백년허리 2: 치료편','『백년허리 2: 치료편』은 가정과 생활, 육아와 건강에 필요한 실용적인 조언을 담은 책이다. 일상에서 바로 적용할 수 있는 방법을 중심으로 구성되어 있어 부담 없이 읽을 수 있다. 더 안정적인 생활 습관과 관계를 만들고 싶은 독자에게 도움이 된다.','정선근','언탱글링',16650,13,'2021-05-13'),
(369,8,9,'각자도생의 세계와 지정학','『각자도생의 세계와 지정학』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','피터 자이한','김앤김북스',17100,191,'2021-02-01'),
(370,3,10,'데일 카네기 자기관리론(국내최초 초판 무삭제 완역본)','『데일 카네기 자기관리론(국내최초 초판 무삭제 완역본)』은 성장과 성과, 돈과 일에 대한 현실적인 고민을 다루는 책이다. 데일 카네기은 추상적인 조언보다 실제 생활에 적용할 수 있는 관점과 행동 방식을 중심으로 이야기를 풀어 간다. 목표를 세우고 꾸준히 실천하려는 독자에게 동기와 기준을 제공한다.','데일 카네기','현대지성',10350,146,'2021-01-13'),
(371,1,11,'천 개의 파랑','천선란의 『천 개의 파랑』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 천 개의 파랑이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','천선란','허블',15300,42,'2020-08-19'),
(372,1,12,'참을 수 없는 존재의 가벼움','밀란 쿤데라의 『참을 수 없는 존재의 가벼움』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 참을 수 없는 존재의 가벼움이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','밀란 쿤데라','민음사',15300,80,'2018-06-20'),
(373,1,13,'노르웨이의 숲','무라카미 하루키의 『노르웨이의 숲』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 노르웨이의 숲이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','무라카미 하루키','민음사',15300,21,'2017-08-07'),
(374,2,14,'달리기를 말할 때 내가 하고 싶은 이야기','『달리기를 말할 때 내가 하고 싶은 이야기』은 무라카미 하루키의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','무라카미 하루키','문학사상',13050,23,'2016-12-15'),
(375,1,15,'종의 기원','정유정의 『종의 기원』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 종의 기원이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','정유정','은행나무',15120,151,'2016-05-16'),
(376,4,16,'나는 3학년 2반 7번 애벌레','『나는 3학년 2반 7번 애벌레』은 어린 독자가 부담 없이 읽으며 지식과 이야기를 함께 즐길 수 있도록 만든 책이다. 친근한 설명과 흥미로운 장면을 통해 나는 3학년 2반 7번 애벌레의 핵심 내용을 자연스럽게 이해하게 한다. 책 읽는 재미를 키우면서 생각하는 힘도 기를 수 있다.','김원아','창비',9900,84,'2016-04-11'),
(377,1,17,'스토너','존 윌리엄스의 『스토너』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 스토너이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','존 윌리엄스','알에이치코리아',15120,188,'2015-01-02'),
(378,1,18,'변신 시골의사','프란츠 카프카의 『변신 시골의사』은 인물의 선택과 관계, 사건의 흐름을 따라가며 삶의 여러 감정을 마주하게 하는 소설이다. 이야기는 변신 시골의사이라는 제목이 암시하는 분위기처럼 독자를 천천히 끌어들이며, 상처와 욕망, 희망이 교차하는 순간들을 섬세하게 보여 준다. 읽고 난 뒤에도 인물들의 마음이 오래 남는 작품이다.','프란츠 카프카','민음사',7650,42,'2009-01-20'),
(379,9,19,'예술의 쓸모','『예술의 쓸모』은 예술과 문화의 세계를 더 가까이 이해하도록 돕는 책이다. 작품과 창작자의 배경을 함께 살펴보며 단순한 감상을 넘어 표현 방식과 시대적 의미까지 생각하게 한다. 문화 콘텐츠를 깊이 있게 즐기고 싶은 독자에게 어울린다.','강은진','다산초당',16200,173,'2020-09-21'),
(380,15,20,'불안','『불안』은 기타 분야의 내용을 독자가 이해하기 쉽게 정리한 책이다. 알랭 드 보통 외의 관점과 설명을 따라가며 주제의 핵심을 부담 없이 파악할 수 있고, 관심 있는 내용을 넓혀 가는 데 도움이 된다.','알랭 드 보통 외','은행나무',14500,135,'2012-08-23'),
(381,8,21,'오디세이아','『오디세이아』은 역사와 사회의 흐름을 배경과 맥락 중심으로 살펴보는 책이다. 사건과 인물을 단순히 암기하는 데서 그치지 않고, 그 시대 사람들이 어떤 선택을 했는지 이해하게 한다. 현재를 바라보는 넓은 시야를 얻을 수 있다.','호메로스','아이템하우스',18000,36,'2026-05-15'),
(382,14,22,'싱글즈(2026년 5월호) 합본호','『싱글즈(2026년 5월호) 합본호』은 정해진 기간 동안 읽기 좋은 묵상과 정보, 다양한 읽을거리를 담은 잡지형 도서다. 짧은 글을 꾸준히 읽으며 생활의 리듬을 잡고, 필요한 내용을 부담 없이 찾아볼 수 있도록 구성되어 있다.','더북컴퍼니 편집부','더북컴퍼니',38000,13,'2026-05-04'),
(383,5,23,'로스쿨 민법의 정석','『로스쿨 민법의 정석』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','정연석','정독',43000,156,'2026-04-22'),
(384,2,24,'화기애애, 아이들과 꽃피는 날들','『화기애애, 아이들과 꽃피는 날들』은 정현진의 시선으로 삶과 마음, 인간관계를 차분히 들여다보는 책이다. 일상에서 쉽게 지나치는 감정과 생각을 붙잡아 독자가 자신의 경험과 연결해 보게 한다. 복잡한 하루 속에서 방향을 잃지 않고 나를 돌아보는 시간을 마련해 준다.','정현진','미다스북스',17550,82,'2026-04-20'),
(385,5,25,'2026 위포트 공기업 NCS 통합 기본서','『2026 위포트 공기업 NCS 통합 기본서』은 학습 목표를 분명히 세우고 실력을 점검하도록 구성된 교재다. 핵심 개념을 빠르게 정리하고 문제 풀이를 통해 약점을 확인할 수 있어 시험 대비에 활용하기 좋다. 반복 학습과 실전 연습을 함께 원하는 독자에게 알맞다.','위포트 연구소','위포트',24300,130,'2026-04-17'),
(386,3,26,'피지컬 AI 2026','『피지컬 AI 2026』은 빠르게 변화하는 디지털 환경 속에서 필요한 기술과 사고방식을 다루는 IT 도서다. 개념 설명에 그치지 않고 실제 활용 장면을 함께 보여 주어 초보자도 흐름을 잡기 쉽다. 데이터와 프로그램을 어떻게 문제 해결에 연결할지 이해하는 데 도움을 준다.','김덕진 외','스마트북스',22500,132,'2026-04-17'),
(387,14,27,'EBS 귀가 트이는 영어(2026년 5월호)','『EBS 귀가 트이는 영어(2026년 5월호)』은 영어 실력을 체계적으로 다지기 위한 학습서로, 이현석의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','이현석','동아출판',11400,122,'2026-04-16'),
(388,14,28,'EBS Easy English 초급 영어회화(2026년 5월호)','『EBS Easy English 초급 영어회화(2026년 5월호)』은 영어 실력을 체계적으로 다지기 위한 학습서로, 이보영의 구성에 따라 핵심 표현과 문제 유형을 단계적으로 익힐 수 있다. 실제 시험이나 일상 학습에서 자주 만나는 어휘와 문법, 독해·청취 포인트를 반복해 연습하게 해 실전 감각을 높여 준다.','이보영','동아출판',8550,97,'2026-04-16'),
(389,14,29,'EBS 중급 일본어(2026년 5월호)','『EBS 중급 일본어(2026년 5월호)』은 정해진 기간 동안 읽기 좋은 묵상과 정보, 다양한 읽을거리를 담은 잡지형 도서다. 짧은 글을 꾸준히 읽으며 생활의 리듬을 잡고, 필요한 내용을 부담 없이 찾아볼 수 있도록 구성되어 있다.','원미령','동아출판',7600,57,'2026-04-16'),
(390,10,30,'통제구역관리부 2','『통제구역관리부 2』은 개성 있는 캐릭터와 빠른 장면 전개로 몰입감을 주는 만화 도서다. 그림과 대사를 통해 인물들의 감정과 관계가 생생하게 드러나며, 시리즈를 따라갈수록 세계관과 이야기가 더욱 풍성해진다.','탄광','다산코믹스(DASAN COMICS)',18900,23,'2026-04-13'),
(391,14,1,'매일성경 순(2026년 5/6월호)','『매일성경 순(2026년 5/6월호)』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','성서유니온 편집부','성서유니온',4750,74,'2026-04-07'),
(392,14,2,'개역개정 작은 매일성경 (2026년5/6월호)','『개역개정 작은 매일성경 (2026년5/6월호)』은 신앙과 내면의 성찰을 돕는 종교 분야 도서다. 일상의 고민 속에서 마음을 가다듬고 자신을 돌아볼 수 있는 문장들이 담겨 있으며, 믿음의 태도와 삶의 방향을 차분히 생각하게 한다.','성서유니온 편집부','성서유니온',4270,132,'2026-04-06');
